(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-step-distill-4step"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-1\">一 · 一次流式直播切片事故：时延被步数锁死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-2\">二 · 它解决的是采样阶段的时间跨度压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-3\">三 · 它不解决的问题：解码、通信、批调度与显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-4\">四 · 适用规模的判断：什么时候该上，什么时候不该上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-5\">五 · 事故复盘的工程判断：先量占比，再定杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-6\">六 · 边界之外：少步蒸馏不解决的问题与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-7\">七 · 教师轨迹的离线生成：监督信号的第一次显存与带宽结算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-8\">八 · 学生前向与步索引嵌入：一次DiT前向的算力账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-9\">九 · 多步展开一致性约束：训练期的展开代价与梯度路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-10\">十 · CFG蒸馏与档位选择：去掉双分支后的条件控制重校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-11\">十一 · 潜变量出口与VAE解码的衔接：步数压缩之后的瓶颈转移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-12\">十二 · 少步蒸馏的失效边界与端到端代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-13\">十三 · 步数档位切换的边界条件与失效代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-14\">十四 · 从教师速度场到学生跨步速度：目标函数逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-15\">十五 · 差商监督的推导：为什么它能替代多步积分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-16\">十六 · 伪代码：可实现的训练循环与展开结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-17\">十七 · 一致性约束的梯度路径与稳定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-18\">十八 · CFG 蒸馏与少步的耦合：去掉双分支后的重校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-19\">十九 · 与量化叠加时的误差预算分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-20\">二十 · 少步蒸馏的失效边界与系统代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-21\">二十一 · 请求形态与步数档位的匹配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-22\">二十二 · 长度分布决定批的构成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-23\">二十三 · 并发与批大小的甜点区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-24\">二十四 · 负载错配的三种失败形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-25\">二十五 · 与量化叠加时的负载约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-26\">二十六 · 负载配方的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-27\">二十七 · 负载配方：请求形态、长度分布与批大小的匹配边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-28\">二十八 · 硬件档位：按步数档位反推SM100/103的算力与显存配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-29\">二十九 · 并行拓扑：TP/SP/PP在少步下的收益重排</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-30\">三十 · 量化方案：FP8与NVFP4在少步下的误差结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-31\">三十一 · KV策略：少步下KV cache的存废与潜变量缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-32\">三十二 · 调度参数：批、步数档位与SLO的联合整定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-33\">三十三 · 档位切换的失效面与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-34\">三十四 · 少步之后的时延结构：DiT 不再是全部</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-35\">三十五 · 显存与带宽：潜变量搬运成为主账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-36\">三十六 · 通信：分离式部署下少步放大同步开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-37\">三十七 · 功耗与热：少步不等于省电</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-38\">三十八 · 尾延迟：规模上去后先崩的是调度粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-39\">三十九 · 失败模式与工程判断的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-40\">四十 · 少步蒸馏的规模拐点：从 DiT 前向到 VAE 解码的代价迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-41\">四十一 · 精度漂移：少步放大数值误差的三条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-42\">四十二 · OOM：潜变量、KV 与分块解码的叠加账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-43\">四十三 · 批抖动与路由不均：步数档位打散批的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-44\">四十四 · 尾延迟尖刺：解码重叠区与重蒸馏切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-45\">四十五 · 监控与回滚：把档位切换做成可逆操作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-46\">四十六 · 少步蒸馏的失效边界与线上诊断：从过饱和到批抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-47\">四十七 · 同族算法的坐标：三条正交的加速轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-48\">四十八 · 决策表：按 SLO 缺口与场景形态选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-49\">四十九 · 选型的量化判据：把 SLO 缺口拆到项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-50\">五十 · 组合顺序与叠加代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-51\">五十一 · 适用条件与不适用清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-step-distill-4step-sec-52\">五十二 · 边界判定：蒸馏、缓存复用与解码侧优化何时互斥</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:525px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 525.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">教师模型在真实采样轨迹上生成中间潜变量与速度场作为监督</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">学生网络输入含步索引嵌入，学习从z_t直接跳到z_{t-Δ}的速度</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练时对学生多步展开做一致性约束，抑制少步下的过饱和与时域坍缩</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">部署时按SLO选步数档位（2/4/8步），配合CFG蒸馏去掉双分支</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出潜变量送入VAE分块解码</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-step-distill-4step-sec-1\">一 · 一次流式直播切片事故：时延被步数锁死</h3>\n<p>某视频生成服务上线交互式“边播边生成”能力：用户上传一段素材，系统在数秒内返回一段可播放的短视频，并支持在播放过程中继续追加后续片段。上线首周，端到端 P99 时延在高峰时段突破交互可接受的窗口，前端播放器反复进入缓冲态。排查结果不在网络、不在调度、也不在 VAE 解码，而在去噪采样本身：模型默认 50 步采样，每一段潜变量都要完整走完 50 次 DiT 前向，端到端时延被采样步数线性放大。用公式表达就是</p>\n<div class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</div>\n<p>其中 $T_{\\text{DiT}}$ 是单次 DiT 前向的时延，$N_{\\text{step}}$ 是采样步数。这个式子的工程含义非常直接：只要 $N_{\\text{step}}$ 还是 50，无论你把单步前向优化到多快、把批调度做得多紧凑、把 KV 与激活显存压得多低，端到端时延的下界都被这个乘数钉住。事故中的服务在 Blackwell 上已经把单步前向压到可接受的水平，但 50 倍乘数仍然把整条链路推到了 SLO 之外；更糟的是，流式场景要求“生成一段、播放一段、再生成下一段”，任何一段的超时都会向后传导，形成级联的缓冲。这就是少步蒸馏要解决的第一个具体问题：<strong>把采样步数这个主导杠杆从 50 压到个位数</strong>，让 DiT 前向时延降一个数量级，从而把交互式与流式服务拉回 SLO 之内。</p>\n<p>需要强调的是，这不是一个“把模型换小”的问题。换小模型会同时损失容量与运动表达能力，而少步蒸馏保持同一基座的表达能力，只改变采样轨迹的长度。事故后的处置也不是加机器：加机器能提高吞吐，却无法缩短单条请求的关键路径时延，因为关键路径的长度由 $N_{\\text{step}}$ 决定，而不是由并发度决定。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-2\">二 · 它解决的是采样阶段的时间跨度压缩</h3>\n<p>少步蒸馏的作用位置非常明确：它作用于<strong>去噪采样阶段</strong>，把多步教师轨迹压缩到 2–8 步的学生轨迹。学生的单步不再只预测一个微小时间间隔的去噪增量，而是直接预测更大时间跨度的增量——从 $z_t$ 直接跳到 $z_{t-\\Delta}$，其中 $\\Delta$ 远大于教师单步的间隔。教师模型在真实采样轨迹上生成中间潜变量与速度场，作为学生的监督信号；学生网络输入中含步索引嵌入，因此同一个网络在不同步数档位下知道自己处在轨迹的哪个位置。训练时对学生多步展开做一致性约束，抑制少步采样下典型的过饱和与时域坍缩。轨迹匹配蒸馏的目标可写为</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathbb{E}_{t,\\Delta}\\Big\\lVert v_\\theta(z_t,t)-\\frac{z_{t}-z_{t-\\Delta}}{\\Delta}\\Big\\rVert^2+\\lambda\\mathcal{L}_{\\text{cons}}$$</div>\n<p>这里第一项让学生速度场逼近教师轨迹在跨度 $\\Delta$ 上的平均速度，第二项 $\\mathcal{L}_{\\text{cons}}$ 约束学生自己多步展开后的落点与教师轨迹一致。工程上，这一项是少步可用性的关键：没有它，学生在 2 步档位下容易出现色彩过饱和与帧间坍缩；有了它，量化误差在少步下也能被部分吸收，因此该算法可以与 FP8/NVFP4 量化叠加使用，而不必在精度与步数之间二选一。</p>\n<p>与相邻算法的边界要划清：VAE 分块重叠解码作用于像素域解码阶段，压缩的是解码的显存与切块开销；缓存复用类方法复用中间激活，不改变网络权重；而少步蒸馏改变的是学生网络的权重与它单步跨越的时间跨度，作用在采样阶段本身。三者可以串联，但各自解决的是不同段的时延。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-3\">三 · 它不解决的问题：解码、通信、批调度与显存</h3>\n<p>适用边界的第一层是“不解决什么”。少步蒸馏把 $N_{\\text{step}}$ 压下来，但它不缩短 VAE 解码的时延，不降低 NVLink 上的通信量，不改变连续批处理的调度策略，也不减少 KV cache 的驻留显存。事故复盘时常见的误判是把所有时延都归因于采样步数，然后在蒸馏之后发现 P99 仍然不达标——此时瓶颈已经转移到解码或跨卡通信。判断方法很朴素：把端到端时延按段拆开，看 $N_{\\text{step}}\\,T_{\\text{DiT}}$ 在总时延中的占比。若占比高，蒸馏是首选杠杆；若占比已经被压到次要位置，继续压步数的边际收益迅速衰减，应该转去处理解码分块、通信重叠或批调度。</p>\n<p>第二层边界是<strong>质量上限受教师轨迹覆盖范围约束</strong>。少步蒸馏损失运动多样性，快速运动与大位移场景易出现拖影与时域坍缩。这不是训练不充分的问题，而是信息论层面的：学生只有 2–8 次前向，单步跨越的时间跨度大，教师轨迹中没有出现过的大位移模式，学生没有可匹配的目标。工程上的应对是在蒸馏数据中覆盖大位移轨迹，或者提高步数档位；但这两者都有代价——前者需要额外的数据管线，后者直接吃掉时延收益。</p>\n<p>第三层边界是<strong>换基座模型需重蒸馏</strong>。学生的步索引嵌入与教师轨迹分布是绑定的；若换了基座而直接复用旧学生权重，步索引嵌入与新的教师轨迹分布不匹配，输出会出现系统性过饱和与色彩偏移。这类故障在灰度发布时表现为“整体色调偏暖、运动幅度偏大”，容易被误判为后处理或色彩管线的问题，实际根因在蒸馏产物与基座的不对齐。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-4\">四 · 适用规模的判断：什么时候该上，什么时候不该上</h3>\n<p>适合上少步蒸馏的负载有清晰特征：请求形态是交互式或流式视频生成，SLO 对首段时延敏感，且 $N_{\\text{step}}\\,T_{\\text{DiT}}$ 在端到端时延中占主导。部署时按 SLO 选步数档位（2/4/8 步），配合 CFG 蒸馏去掉双分支以减半前向计算；输出潜变量送入 VAE 分块解码。步数从 50 降到 4 使 DiT 前向时延降一个数量级，这是流式视频服务的关键杠杆。档位选择本身是一个容量规划问题：2 步档位时延最低但运动多样性最弱，8 步档位质量更稳但时延收益收窄，4 步通常是交互式服务的折中点。档位不是静态配置，而应随请求的运动幅度与 SLO 等级动态切换。</p>\n<p>不适合上的情形同样明确。第一，离线批处理场景对单条时延不敏感，吞吐由批大小与显存决定，压步数带来的吞吐收益有限，却要承担重蒸馏与质量损失的成本。第二，以慢动作、静态构图为主的内容，运动多样性损失不明显，蒸馏的收益主要体现在时延上，若时延本就不是瓶颈则不值得。第三，基座模型迭代频繁的团队要谨慎：每次换基座都要重蒸馏，蒸馏需要教师轨迹数据与额外训练管线，这条管线的维护成本会随基座更迭频率线性增长。第四，CFG 蒸馏去掉双分支后若引导强度未重新校准，少步采样下条件控制减弱，文本对齐与运动幅度同时退化——这类退化在 A/B 中表现为“提示词遵循变差”，根因却在引导强度的重标定，而不是蒸馏本身。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-5\">五 · 事故复盘的工程判断：先量占比，再定杠杆</h3>\n<p>把这次事故抽象成一条工程判断规则：面对端到端时延超标，先按 $T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$ 拆解，量出采样段在关键路径上的占比，再决定是否引入少步蒸馏。占比高时，蒸馏是唯一能改变乘数的杠杆，量化、批调度、显存优化都只能改变 $T_{\\text{DiT}}$ 或并发度，无法改变 $N_{\\text{step}}$。占比低时，蒸馏的边际收益被解码与通信吃掉，应优先处理那些段。事故中的服务在蒸馏后把 50 步压到 4 步，DiT 前向时延降一个数量级，流式播放的缓冲态消失；但复盘也确认，若当时解码段没有做分块重叠，单靠蒸馏仍不足以达标——这正说明适用边界不是“蒸馏万能”，而是“蒸馏解决它该解决的那一段”。</p>\n<p>另一个判断点是失败模式的预警信号。少步档位上线后若观察到快速运动场景的拖影、时域坍缩、或换基座后的系统性过饱和与色彩偏移，应首先检查三件事：蒸馏数据是否覆盖大位移轨迹、步索引嵌入是否与新基座对齐、CFG 引导强度是否重新校准。这三项检查对应三条已知失败模式，且都不需要重新设计算法，只需要在蒸馏管线与部署配置上做修正。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-6\">六 · 边界之外：少步蒸馏不解决的问题与失效条件</h3>\n<p>一次典型的线上事故足以说明这个算法的必要性：流式视频服务按 50 步默认采样上线，单帧端到端时延被采样步数线性放大，交互式会话的 SLO 在并发上升时被击穿，而算力并未打满——瓶颈在采样循环本身。此时增加 GPU 或换更大显存都无效，因为时延的主导杠杆是步数，不是吞吐资源。少步蒸馏正是针对这一杠杆：把教师的多步轨迹压缩到 2–8 步学生，使 DiT 前向时延降一个数量级。但它只压缩去噪采样阶段，对 VAE 分块解码、调度排队、网络往返这些同样计入端到端时延的分量不产生任何作用；若服务侧时延预算中解码与排队占比高，蒸馏带来的收益会被稀释。它也不解决显存容量与 KV 类缓存问题，不改变单请求的批形状约束，更不提升教师本身的能力上限。</p>\n<p>失效条件有三类，且都与部署决策直接相关。其一是运动多样性：少步蒸馏损失运动多样性，快速运动与大位移场景易出现拖影与时域坍缩，这是学生单步跨越更大时间跨度时速度场被过度平滑的必然代价。其二是基座漂移：换基座模型未重蒸馏而直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出出现系统性过饱和与色彩偏移——步索引嵌入是学生输入的一部分，它编码的是特定教师轨迹的离散化方式，不可迁移。其三是引导失配：CFG 蒸馏去掉双分支后若引导强度未重新校准，少步采样下条件控制减弱，文本对齐与运动幅度同时退化。三者都不是训练损失下降能自动暴露的，必须在蒸馏数据中覆盖大位移轨迹、按基座版本绑定学生权重、并对引导强度做少步条件下的重新标定。</p>\n<p>系统代价需按档位核算。设单步 DiT 前向耗时为 <span class=\"formula-inline\">$$T_{\\text{DiT}}$$</span>，则生成时延近似为 <span class=\"formula-inline\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</span>，配合 CFG 蒸馏去掉双分支后单步计算再减半。步数档位 2/4/8 的选择本质是 SLO 与质量的权衡：2 步把时延压到最低但时域坍缩风险最高，8 步保留更多运动细节却牺牲时延余量。下表给出定性判断而非实测值。</p>\n<table class=\"mini\"><thead><tr><th>步数档位</th><th>时延量级</th><th>运动保真</th><th>适用场景</th></tr></thead><tbody><tr><td>2 步</td><td>最低</td><td>弱，拖影风险高</td><td>强交互预览、低动态内容</td></tr><tr><td>4 步</td><td>较 50 步降一个数量级</td><td>中等</td><td>常规流式服务默认档</td></tr><tr><td>8 步</td><td>高于 4 步</td><td>较强</td><td>大位移、快速运动场景</td></tr></tbody></table>\n<p>还有一笔常被忽略的代价：蒸馏需要教师轨迹数据与额外训练管线，换基座模型需重蒸馏，这意味着学生权重与基座版本强绑定，模型升级路径从“换权重”变成“重跑蒸馏”。与缓存复用类方法相比，蒸馏改变的是学生网络权重而非复用中间激活，因此它不能与“跳过某些步”的运行时技巧叠加获得双重收益，二者作用于同一杠杆。可与 FP8/NVFP4 量化叠加，量化误差在少步下被一致性约束部分吸收，但量化与蒸馏的误差会在大位移轨迹上叠加放大，需在档位选择时留出余量。工程判断是：把少步蒸馏当作时延杠杆而非质量杠杆，档位按 SLO 动态切换，并在蒸馏数据中显式覆盖目标场景的运动分布，否则事故会从“太慢”变成“太快但不对”。</p>\n<h3 id=\"alg-step-distill-4step-sec-7\">七 · 教师轨迹的离线生成：监督信号的第一次显存与带宽结算</h3>\n<p>少步蒸馏的数据流起点不在学生网络，而在教师模型的采样轨迹上。教师以默认50步（或更高）的调度器在真实请求分布上跑完整去噪，沿途把每个中间潜变量 <span class=\"inline-math\">z<sub>t</sub></span> 与对应的速度场 <span class=\"inline-math\">v<sub>tea</sub>(z<sub>t</sub>,t)</span> 落盘。这一步的输入是提示词、初始噪声与采样调度；输出是一串按时间步索引的（潜变量，速度）对，构成学生要回归的目标。代价首先体现在存储与带宽：潜变量张量的规模由分辨率、帧数与通道数决定，一条50步轨迹意味着50份中间态，若训练集覆盖数千条提示词，轨迹库的容量与读取吞吐会直接决定蒸馏管线的数据加载是否成为瓶颈。工程上通常只保留与目标步数档位对齐的稀疏锚点（例如4步档位取若干关键时间步），并对潜变量做通道级量化存储，把磁盘到HBM的搬运量压下来。第二个代价是教师前向本身：教师是完整的多步模型，生成轨迹的算力开销等价于一次完整推理，因此轨迹库的构建是一次性离线成本，但换基座模型即需重建，这与适用边界中“换基座需重蒸馏”的判断同源。一个具体例子：为4步档位准备监督时，教师轨迹只需在 <span class=\"inline-math\">t=1.0→0.75→0.5→0.25→0</span> 的锚点上取样，学生学的是每一段大跨度的平均速度，而非50个微步的瞬时速度。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-8\">八 · 学生前向与步索引嵌入：一次DiT前向的算力账</h3>\n<p>学生网络的输入除潜变量 <span class=\"inline-math\">z<sub>t</sub></span> 外，还含一个步索引嵌入，把“当前处于第几档、跨度为多大”编码进条件通路。这是少步蒸馏区别于普通微调的关键机制：同一个学生权重要在2、4、8步三种调度下都给出正确的增量方向，步索引嵌入就是切换行为的开关。前向输出是速度 <span class=\"inline-math\">v<sub>θ</sub>(z<sub>t</sub>,t)</span>，经一次欧拉式更新得到 <span class=\"inline-math\">z<sub>t−Δ</sub></span>。单步代价可用 <span class=\"inline-math\">T<sub>gen</sub>≈N<sub>step</sub>·T<sub>DiT</sub></span> 直接结算：步数从50降到4，DiT前向次数降一个数量级，端到端时延随之线性收缩，这是流式服务能否满足SLO的主导杠杆。但单次前向的代价并未变小——学生仍是完整DiT，注意力与卷积的算力、激活显存、权重带宽与50步时同量级，省的是次数而非单次。因此在Blackwell上，少步蒸馏与FP8/NVFP4量化是正交叠加的两层：量化压单次前向的带宽与算力，蒸馏压次数。一个具体例子：4步档位下每步跨度Δ=0.25，学生一次前向要预测0.25个时间单位的位移，其速度场幅度约为教师单步的25倍，数值动态范围更大，这也是量化误差需要被一致性约束吸收的原因。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-9\">九 · 多步展开一致性约束：训练期的展开代价与梯度路径</h3>\n<p>训练时学生不是单步回归，而是把自身多步展开串起来做一致性约束。伪代码思路是：从真实轨迹某锚点取 <span class=\"inline-math\">z<sub>t</sub></span>，用学生连续推 <span class=\"inline-math\">k</span> 步得到 <span class=\"inline-math\">z<sub>t−kΔ</sub></span>，再与教师在同一终点的潜变量比对，同时约束沿途速度与教师锚点速度的匹配。目标函数为</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathbb{E}_{t,\\Delta}\\Big\\lVert v_\\theta(z_t,t)-\\frac{z_{t}-z_{t-\\Delta}}{\\Delta}\\Big\\rVert^2+\\lambda\\mathcal{L}_{\\text{cons}}$$</div>\n<p>第一项是轨迹匹配，第二项是展开一致性。展开的代价是训练吞吐：<span class=\"inline-math\">k</span> 步展开意味着一次参数更新要跑 <span class=\"inline-math\">k</span> 次学生前向并保留中间激活以反传，显存占用随 <span class=\"inline-math\">k</span> 线性上升，梯度路径也变长。工程上以梯度检查点与短展开（k取2–3）折中，把一致性约束的作用限制在相邻档位之间，避免长展开把显存打爆。这一项的收益直接对应失败模式：没有它，少步学生在快速运动与大位移场景会出现过饱和与时域坍缩；有了它，量化误差在少步下被部分吸收。一个具体例子：文本条件在少步下容易过度强化，一致性约束把展开终点的色彩统计拉回教师分布，抑制系统性过饱和。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-10\">十 · CFG蒸馏与档位选择：去掉双分支后的条件控制重校准</h3>\n<p>部署侧的第一道机制是CFG蒸馏：把无条件和有条件两条分支合并进单次学生前向，前向计算减半。输入是带引导强度的条件嵌入，输出是已内含引导效果的速度场。代价出现在条件控制上——去掉双分支后引导强度不再由两次前向的线性外推给出，必须在蒸馏目标里重新校准，否则少步采样下文本对齐与运动幅度同时退化，这正是给定失败模式之一。第二道机制是档位选择：按SLO在2/4/8步间切换，2步档位时延最低但运动多样性最弱，8步档位接近教师质量但前向次数翻倍。档位切换的代价是调度器与步索引嵌入必须同步，缓存复用类方法在这里帮不上忙——蒸馏改的是权重，不是中间激活，所以档位切换不能靠复用上一次请求的激活来摊销。一个具体例子：交互式预览用2步档位、终稿渲染用8步档位，同一学生权重靠步索引嵌入切换，服务端只需改调度参数而不换模型。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-11\">十一 · 潜变量出口与VAE解码的衔接：步数压缩之后的瓶颈转移</h3>\n<p>学生输出的最终潜变量送入VAE分块解码，这是数据流的最后一环，也是步数压缩后瓶颈转移的位置。输入是少步采样得到的潜变量序列，输出是像素帧。代价结构发生变化：DiT前向从50次降到4次后，VAE解码在端到端时延中的占比显著上升，分块重叠解码的吞吐与显存带宽成为新的约束；若VAE仍按50步时代的预算配置，整体SLO不会随步数下降而同比例改善。工程判断是：少步蒸馏必须与解码侧的分块策略联合调参，把省下来的DiT时间让给更大分辨率或更长帧数，而不是让VAE成为固定开销。另一个衔接点是数值一致性——少步潜变量的动态范围更大，VAE解码前的反归一化与量化反量化必须与训练时的统计匹配，否则色彩偏移会在解码后被放大。一个具体例子：4步档位下潜变量的通道方差高于50步轨迹，若VAE入口仍用教师轨迹的缩放系数，输出会出现整体亮度漂移，这类误差在蒸馏数据覆盖不足的大位移片段上最明显。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-12\">十二 · 少步蒸馏的失效边界与端到端代价账</h3>\n<p>把步数从 50 压到 4，收益是 DiT 前向次数减少一个量级，但这条杠杆有明确的断裂点：学生网络学的是教师轨迹上的局部速度，一旦推理时的输入潜变量偏离教师轨迹覆盖的流形，少步展开没有纠错机会，误差被一次性放大到输出。失效的第一类条件是运动幅度超出蒸馏数据分布——快速运动、大位移、镜头切换这类样本在教师轨迹中占比低，学生在 Δ 较大时倾向输出平滑的速度场，表现为拖影与时域坍缩；第二类条件是基座替换，步索引嵌入与教师轨迹分布绑定，直接复用旧学生权重会出现系统性过饱和与色彩偏移，必须重蒸馏；第三类条件是 CFG 蒸馏后引导强度未重新校准，去掉了双分支使前向计算减半，但少步下条件控制减弱，文本对齐与运动幅度同时退化。这三类失效都不是靠调采样器能补救的，只能回到蒸馏数据覆盖与档位选择上处理。</p>\n<p>把代价写成账本，端到端时延并不只由 DiT 决定。设单步 DiT 前向为 <span class=\"formula\">$$T_{\\text{DiT}}$$</span>，采样段时延近似 <span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</span>，但请求总时延还要叠加 VAE 分块解码、潜变量搬运与调度排队。步数从 50 降到 4 时，DiT 段压缩一个量级，VAE 解码与首块出图延迟随即成为新的主导项——这正是本算法与 VAE 分块重叠解码必须联合调优的原因：前者压去噪阶段，后者压像素域解码，两者作用于不同阶段，缺一个则端到端 SLO 仍被另一段卡住。与缓存复用类方法相比，蒸馏改变的是学生权重而非复用中间激活，因此它不依赖请求间的相似性，对流式服务的长尾请求同样有效，代价是权重与训练管线的一次性投入。</p>\n<p>部署侧按 SLO 选档位是这套方案的核心工程判断，而不是把 4 步当默认值。2 步档位适合首帧快速出图与低分辨率预览，4 步是交互式服务的主力档，8 步用于大位移与高动态场景兜底；档位切换意味着同一基座要维护多套学生权重与对应的步索引嵌入，显存占用与权重加载时间随档位数上升。与 FP8/NVFP4 量化叠加时，量化误差在少步下被一致性约束部分吸收，但吸收能力有上限：步数越少，单步承担的数值跨度越大，低精度下速度场的尾部误差更容易在少步展开中累积，因此量化校准集应覆盖各档位实际使用的步数与引导强度，而不是只按教师 50 步轨迹标定。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测征兆</th><th>工程处置</th></tr></thead><tbody><tr><td>大位移轨迹覆盖不足</td><td>快速运动段拖影、时域坍缩</td><td>蒸馏数据补大位移样本，或升档至 8 步</td></tr><tr><td>换基座未重蒸馏</td><td>系统性过饱和、色彩偏移</td><td>重跑教师轨迹与蒸馏管线</td></tr><tr><td>CFG 蒸馏后引导未校准</td><td>文本对齐与运动幅度同时退化</td><td>按档位重扫引导强度</td></tr></tbody></table>\n<p>训练侧代价同样要计入容量规划：蒸馏需要教师模型在真实采样轨迹上生成中间潜变量与速度场，这条管线占用教师前向算力与轨迹存储，且换基座即作废；多步展开的一致性约束把训练图从单步拉长到数步，反向传播的激活显存与时延随展开步数线性上升。因此少步蒸馏不是一次性的离线优化，而是与基座版本、量化档位、SLO 档位三者绑定的持续维护项——把它当作静态权重交付，失效条件会在流量高峰的大位移请求上集中暴露。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-13\">十三 · 步数档位切换的边界条件与失效代价</h3>\n<p>部署时按 SLO 在 2/4/8 步间切换，看似只是改一个配置项，实际牵动整条数据流的三处耦合。步索引嵌入把离散档位编码进学生网络的条件输入，因此同一份学生权重在不同档位下的速度场估计并不是简单的“同一函数采样更粗”，而是三套被联合训练过的子分布；跨档位热切换必须确认该档位在蒸馏时被显式覆盖，否则一致性约束只在训练分布内成立。CFG 蒸馏去掉双分支使前向计算减半，但引导强度需随档位重新标定：2 步档下条件与无条件分支的差异被压缩进单次前向，若沿用 4 步档的引导系数，文本对齐与运动幅度会同时退化，表现为提示词约束变弱而画面趋于平缓。VAE 分块解码与 DiT 前向是串行两段，步数压缩只缩短前段，当 DiT 时延降到与分块解码同量级时，端到端瓶颈转移到像素域解码，此时继续压步数的边际收益迅速衰减。</p>\n<p>失效条件的系统代价可以写成一条可核算的判据。设单步 DiT 前向时延为 $T_{\\text{DiT}}$，则 $T_{\\text{gen}}\\approx N_{\\text{step}}T_{\\text{DiT}}+T_{\\text{VAE}}$，档位从 4 步降到 2 步只节省 $2T_{\\text{DiT}}$，而运动多样性损失却是非线性的：快速运动与大位移场景在 2 步档下出现拖影与时域坍缩的概率显著上升，因为学生单步跨越的时间跨度 $\\Delta$ 变大，教师轨迹在该跨度内的速度场非单调性无法被单一增量拟合。工程判断是：交互式首帧可用 2 步档抢时延，流式连续帧应回到 4 步档以维持时域连贯；8 步档留给大位移或高动态内容，作为多样性兜底而非默认。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>DiT 前向占比</th><th>主要风险</th><th>适用请求形态</th></tr></thead><tbody><tr><td>2 步</td><td>最低</td><td>拖影、时域坍缩、引导减弱</td><td>首帧预览、低动态交互</td></tr><tr><td>4 步</td><td>中</td><td>快速运动边缘模糊</td><td>流式连续帧默认</td></tr><tr><td>8 步</td><td>较高</td><td>时延回升，逼近 VAE 瓶颈</td><td>大位移、高动态内容</td></tr></tbody></table>\n<p>换基座模型是另一条硬边界：学生权重的步索引嵌入与教师轨迹分布绑定，未重蒸馏而直接复用会出现系统性过饱和与色彩偏移，这类误差不会被 FP8/NVFP4 量化误差掩盖，反而在少步下被放大。蒸馏数据必须覆盖大位移轨迹，否则多样性上限由教师轨迹覆盖范围决定，而非由学生容量决定；这与缓存复用类方法改变的是不同对象——后者复用中间激活、不触碰权重，因此换模型无需重训，而蒸馏的迁移成本必须计入模型迭代周期。</p>\n<h3 id=\"alg-step-distill-4step-sec-14\">十四 · 从教师速度场到学生跨步速度：目标函数逐项拆解</h3>\n<p>本片段只做一件事：把轨迹匹配蒸馏的目标函数拆到每一项都能对应到张量、对应到一次前向、对应到一份显存账单，并给出可直接落地的伪代码结构。先看完整式：</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathbb{E}_{t,\\Delta}\\Big\\lVert v_\\theta(z_t,t)-\\frac{z_{t}-z_{t-\\Delta}}{\\Delta}\\Big\\rVert^2+\\lambda\\mathcal{L}_{\\text{cons}},\\quad T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</div>\n<p>逐项读。第一项是回归项，期望遍历时间步 $$t$$ 与跨步长度 $$\\Delta$$。被回归的量不是教师网络的瞬时输出，而是<strong>轨迹上的差商</strong> $$\\frac{z_t-z_{t-\\Delta}}{\\Delta}$$——即教师真实采样轨迹在 $$[t-\\Delta,\\,t]$$ 区间上的平均速度。这是推导的关键一步：少步学生要预测的不是某一点的速度，而是整段区间的等效位移速率。把差商作为监督目标，等价于要求学生单次前向的输出在数值上等于教师多次前向的累积效果除以步数，从而把“多步积分”折叠进“单次回归”。</p>\n<p>第二项 $$\\lambda\\mathcal{L}_{\\text{cons}}$$ 是权重为 $$\\lambda$$ 的一致性约束，作用对象是学生的多步展开：学生从 $$z_T$$ 出发连续跳若干次 $$\\Delta$$，把展开终点与教师轨迹同一时刻的潜变量对齐。回归项管单步精度，一致性项管多步复合误差不累积——少步采样最怕的正是单步小误差在 2–4 次跳跃后被放大成过饱和与色彩漂移。</p>\n<p>右侧的时延式 $$T_{\\text{gen}}\\approx N_{\\text{step}}T_{\\text{DiT}}$$ 是这套方法的全部工程动机：端到端时延对步数近似线性。把 50 步压到 4 步，DiT 前向部分降一个数量级；但注意此式忽略了 VAE 解码与调度开销，因此步数压到 2 步以下时，收益会被非 DiT 部分吃掉，这也是档位停在 2/4/8 而非 1 的原因。代价侧要写清楚：回归项用差商替代瞬时速度，等于把监督信号的时间分辨率调粗，教师轨迹中高频的运动细节在 $$\\Delta$$ 较大的区间被平均掉，这就是少步蒸馏损失运动多样性的数学来源。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-15\">十五 · 差商监督的推导：为什么它能替代多步积分</h3>\n<p>把教师的采样过程写成前向欧拉积分：$$z_{t-\\Delta}=z_t-\\Delta\\,v_{\\text{tea}}(z_t,t)$$。若学生要一次跳跃复现这一步，则学生输出应满足 $$v_\\theta(z_t,t)=\\frac{z_t-z_{t-\\Delta}}{\\Delta}$$。对多步情形，学生连续跳 $$k$$ 次到达 $$z_{t-k\\Delta}$$，教师走 $$k$$ 步到达同一点；把 $$k$$ 步欧拉式相加并除以 $$k\\Delta$$，得到区间平均速度恰为各步速度的算术平均。于是“学生单步预测区间平均速度”与“教师多步积分”在离散欧拉意义下严格等价——这是推导链条上唯一需要写下来的恒等关系，其余都是它的推论。</p>\n<p>但等价只在教师轨迹上成立。学生一旦偏离轨迹，$$z_t$$ 就不再是教师访问过的点，差商监督失效。这正是需要 $$\\mathcal{L}_{\\text{cons}}$$ 的原因：一致性项把学生自己展开出的中间点拉回教师轨迹邻域，使回归项在后续步仍然有定义。工程上这对应一个具体做法——训练时对学生展开的每一步都计算与教师轨迹的偏差，而不是只算最后一步。</p>\n<p>代价体现在训练侧：每个样本要跑教师完整轨迹（50 步量级）产生监督，再跑学生多步展开，单次迭代的 DiT 前向次数是纯监督训练的数十倍。教师轨迹数据因此成为固定成本，换基座模型必须重蒸馏，学生权重不能跨基座复用——步索引嵌入与教师轨迹分布一旦不匹配，输出会出现系统性过饱和。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-16\">十六 · 伪代码：可实现的训练循环与展开结构</h3>\n<p>下面给出落到张量级的结构，不含框架细节。核心是把“教师轨迹采样”“差商构造”“学生多步展开”“一致性回传”四段分开，便于插入混合精度与检查点。</p>\n<ul>\n<li>阶段 A：教师轨迹采样。固定教师权重，从噪声 $$z_T$$ 起按调度器走完整轨迹，缓存每个访问点的 $$(z_t,\\,t,\\,v_{\\text{tea}})$$。缓存粒度按 $$\\Delta$$ 对齐，避免训练时再做插值。</li>\n<li>阶段 B：构造监督对。对每个缓存点取 $$(z_t,\\,z_{t-\\Delta})$$，算差商作为回归目标；同时保留 $$v_{\\text{tea}}(z_t,t)$$ 供诊断用。</li>\n<li>阶段 C：学生展开。输入 $$z_t$$ 与步索引嵌入 $$e(t,\\Delta)$$，学生输出跨步速度，按欧拉式推进到 $$z_{t-\\Delta}^{\\theta}$$；重复 $$k$$ 次得到展开终点。</li>\n<li>阶段 D：损失合成。回归项在展开的每一步都算（不只在首步），一致性项对齐展开终点与教师缓存点；两项按 $$\\lambda$$ 加权后反传。</li>\n</ul>\n<p>伪代码思路可压成四行：</p>\n<div class=\"formula\">$$\\text{for } (z_t,z_{t-\\Delta},v_{\\text{tea}}) \\in \\text{cache}:\\; \\hat v \\leftarrow v_\\theta(z_t,e(t,\\Delta));\\; z_{t-\\Delta}^{\\theta}\\leftarrow z_t-\\Delta\\hat v;\\; \\mathcal{L}\\mathrel{+}=\\lVert\\hat v-\\tfrac{z_t-z_{t-\\Delta}}{\\Delta}\\rVert^2+\\lambda\\lVert z_{t-k\\Delta}^{\\theta}-z_{t-k\\Delta}^{\\text{tea}}\\rVert^2$$</div>\n<p>实现上有三个必须落到的细节。其一，步索引嵌入必须与 $$\\Delta$$ 绑定而非只与 $$t$$ 绑定，否则同一 $$t$$ 下不同档位（2/4/8 步）的学生会互相干扰；工程上按档位分桶训练或把 $$\\Delta$$ 作为连续条件输入。其二，展开的 $$k$$ 要与部署档位一致——训练时展开 4 步、部署却用 2 步，一致性约束覆盖不到 2 步路径，少步下过饱和会重新出现。其三，回归项在展开中间步也要算，否则误差在第二步起无人约束。</p>\n<p>系统代价：阶段 A 的教师轨迹缓存是显存与带宽的主要开销，缓存全部中间潜变量在长视频上按帧数线性增长；实务上按批采样、边采边训，把缓存压到单批生命周期内。阶段 C 的展开使单次迭代的学生前向次数等于 $$k$$，训练吞吐约为普通监督训练的 $$1/k$$，这是蒸馏管线额外训练成本的直接来源。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-17\">十七 · 一致性约束的梯度路径与稳定性</h3>\n<p>一致性项对 $$\\lambda$$ 敏感。$$\\lambda$$ 过小，展开终点漂移，少步采样出现时域坍缩（相邻帧趋于同一潜变量，运动幅度塌陷）；$$\\lambda$$ 过大，回归项被压制，学生退化为复制教师单步速度，跨步能力丢失，步数压不下去。稳定的做法是让 $$\\lambda$$ 随 $$\\Delta$$ 增大而增大：跨步越大，单步误差被复合放大的倍数越高，越需要终点对齐来兜底。这解释了为什么 8 步档位可以用较小 $$\\lambda$$、2 步档位必须用较大 $$\\lambda$$。</p>\n<p>梯度路径上有一个容易忽略的点：一致性项对学生展开的中间步求导时，梯度会穿过学生自身的输出，形成“学生监督学生”的回路。若展开步数 $$k$$ 较大而 $$\\lambda$$ 又大，这个回路会让梯度范数随 $$k$$ 指数增长，训练不稳定。工程对策是对展开中间步做梯度截断（只对终点回传，中间步视为常量），或按 $$k$$ 缩小 $$\\lambda$$。这与数值精度叠加时尤其重要：FP8/NVFP4 量化下学生输出本身带量化噪声，回路会放大噪声，表现为训练后期损失震荡。</p>\n<p>具体例子：交互式视频服务选 4 步档位，训练时 $$k=4$$、$$\\Delta$$ 对应 50/4 的区间，$$\\lambda$$ 取使两项量级相当的值；若同一学生要下探到 2 步，需单独用 $$k=2$$ 的展开路径再训一轮或加一个 2 步桶，不能直接复用 4 步权重——这是档位切换在训练侧的真实成本，也是“按 SLO 选档位”在工程上必须提前规划的原因。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-18\">十八 · CFG 蒸馏与少步的耦合：去掉双分支后的重校准</h3>\n<p>CFG 蒸馏把无条件与有条件两次前向合并为一次，前向计算减半，是少步档位能否落地的另一半杠杆。其目标可写成让学生单次输出逼近教师 CFG 合成结果：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{cfg}}=\\mathbb{E}\\Big\\lVert v_\\theta(z_t,t,c)-v_{\\text{tea}}(z_t,t)+\\big(w-1\\big)\\big(v_{\\text{tea}}(z_t,t,c)-v_{\\text{tea}}(z_t,t)\\big)\\Big\\rVert^2$$</div>\n<p>其中 $$w$$ 为引导强度。关键在于：少步采样下引导强度的最优值与多步不同。多步时每步都施加引导，误差被后续步修正；少步时引导一次性注入，过强会导致过饱和，过弱则文本对齐与运动幅度同时退化。因此 CFG 蒸馏完成后必须重新校准 $$w$$，且校准要在目标步数档位上做，不能沿用教师 50 步的最优值。</p>\n<p>系统代价上，CFG 蒸馏省下的是每步一次无条件前向，在 4 步档位下等于把 DiT 前向总量再砍一半；但校准不当会让省下的算力换回质量回退，表现为文本条件控制减弱。工程判断：CFG 蒸馏与轨迹匹配蒸馏应联合训练而非串行两阶段，否则学生在去双分支后失去条件分支的监督，$$w$$ 的重校准缺少依据。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-19\">十九 · 与量化叠加时的误差预算分配</h3>\n<p>少步蒸馏与 FP8/NVFP4 量化叠加时，两类误差进入同一个预算。量化误差是逐次前向的加性扰动，少步下前向次数少，扰动被复合放大的机会也少；一致性约束在训练时已把学生输出拉向轨迹，等于给量化噪声留出了容差。但这条容差有边界：跨步 $$\\Delta$$ 越大，单次前向承担的位移越大，同样的量化相对误差在潜变量上造成的绝对偏移越大，快速运动与大位移场景最先出问题，表现为拖影。</p>\n<p>可落地的分配原则：先定量化位宽再定步数档位，而非反过来。因为量化误差在 8 步档位下被更多次前向平均、在 2 步档位下集中暴露；若业务 SLO 要求 2 步，则量化应停在 FP8 而非 NVFP4，把误差预算留给跨步回归。反过来，若量化已压到 NVFP4，步数档位不宜低于 4，否则两类误差叠加会突破一致性约束的吸收能力。这一判断不依赖具体实验数字，只依赖误差复合的次数结构：$$N_{\\text{step}}$$ 越小，单步误差预算越紧。</p>\n<p>最后落到一个具体机制上：训练时在展开路径中插入量化-反量化模拟（fake quant），让一致性约束在带量化噪声的学生输出上学习终点对齐，而不是在干净权重上学完后直接部署量化版本。这样 $$\\lambda$$ 吸收的是真实部署噪声，档位切换与位宽切换才不必各自重训一轮。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-20\">二十 · 少步蒸馏的失效边界与系统代价核算</h3>\n<p>轨迹匹配蒸馏把监督信号绑在教师真实采样轨迹上，学生输入含步索引嵌入，从 <span>z_t</span> 直接回归跨 Δ 的去噪增量。关键一步在于一致性项并非简单正则，而是对学生自身多步展开的复合误差做惩罚：设学生展开 N 步得到 <span>ẑ_{t-NΔ}</span>，则 <span class=\"formula\">$$\\mathcal{L}_{\\text{cons}}=\\mathbb{E}\\big\\lVert \\hat{z}_{t-N\\Delta}-z_{t-N\\Delta}^{\\text{tea}}\\big\\rVert^2$$</span>，它把单步回归误差沿展开链累积放大后的偏差压回去，这正是抑制少步过饱和与时域坍缩的作用点。但该约束只在教师轨迹覆盖的流形邻域内有效：一旦请求的运动幅度超出蒸馏数据中的位移分布，学生没有可对齐的展开终点，一致性项退化为对自身错误的自洽，输出表现为拖影而非校正。</p>\n<p>失效条件可归为三类，均需在部署前判定而非运行中补救。其一是运动多样性上限：少步蒸馏以牺牲轨迹分支换取步数压缩，快速运动与大位移场景的拖影是结构性代价，只能靠蒸馏数据覆盖大位移轨迹或把步数档位从 2/4 步上调至 8 步缓解。其二是基座漂移：换基座模型而未重蒸馏时，步索引嵌入与教师轨迹分布不匹配，输出出现系统性过饱和与色彩偏移，这类错误在一致性约束下不会被发现，因为学生仍在“自洽”。其三是 CFG 蒸馏后引导强度未重校准，去掉双分支使前向计算减半，但少步下条件控制减弱，文本对齐与运动幅度同时退化。</p>\n<p>系统代价须与收益同表核算。<span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}+T_{\\text{VAE}}$$</span>，步数从 50 降到 4 使 DiT 前向时延降一个数量级，但 <span>\\(T_{\\text{VAE}}\\)</span> 分块解码不随步数缩小，步数越低其占比越高，2 步档位下端到端时延由解码而非采样主导，此时继续压步数收益递减。显存侧，蒸馏本身不增推理显存，但保留教师轨迹数据与重蒸馏管线是离线成本；换基座即触发全量重蒸馏，构成模型迭代的固定开销。精度侧，与 FP8/NVFP4 量化叠加时量化误差被一致性约束部分吸收，但该吸收依赖展开终点可信，故量化校准应与步数档位联合验证，而非独立通过。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>DiT 前向</th><th>主要风险</th><th>适用判断</th></tr></thead><tbody><tr><td>2 步</td><td>最低</td><td>拖影、时域坍缩最重</td><td>仅低运动、强 SLO 场景</td></tr><tr><td>4 步</td><td>降一个数量级</td><td>大位移下多样性不足</td><td>流式服务默认档</td></tr><tr><td>8 步</td><td>仍显著低于 50 步</td><td>时延回升</td><td>快速运动兜底档</td></tr></tbody></table>\n<p>工程判断落在档位切换的触发条件上：以请求的运动幅度估计（光流或文本运动词）作为路由信号，超阈值即升档，而非等 SLO 违约后被动回退；同时把重蒸馏纳入基座升级的发布门禁，未重蒸馏的学生权重不得与新基座混用。</p>\n<h3 id=\"alg-step-distill-4step-sec-21\">二十一 · 请求形态与步数档位的匹配</h3>\n<p>少步蒸馏的负载配方首先由请求形态决定。交互式与流式视频生成是它的主战场：用户在前端等待首帧或首段，SLO 以“首段可见时延”和“段间间隔”计，而不是以整段视频的总生成时间计。这类请求的到达是泊松式的、突发性强，单请求的算力需求却随步数档位线性变化。部署时按 SLO 在 2/4/8 步之间切换，本质上是把一个连续的时延-质量曲线离散成三档，让调度器可以在负载高峰把请求压到 2 步档、在空闲时段放回 8 步档。步数档位不是全局配置，而是每请求可选的参数——这一点决定了它必须与批调度器耦合，而不是写死在模型服务里。</p>\n<p>机制上，步索引嵌入让学生网络知道自己当前处于哪一档：2 步档的 Δ 大，单步跨越的时间跨度长，学生必须一次预测出更大的去噪增量；8 步档的 Δ 小，学生退化为接近教师的细粒度采样。因此同一份学生权重可以服务三档，但每档的有效感受野与误差累积特性不同。用公式表达档位对时延的支配关系：</p>\n<div class=\"formula\">$$T_{\\text{req}} \\approx N_{\\text{step}}\\,T_{\\text{DiT}} + T_{\\text{VAE}} + T_{\\text{queue}}$$</div>\n<p>其中 $T_{\\text{DiT}}$ 是单次前向的时延，$T_{\\text{VAE}}$ 是分块解码的时延，$T_{\\text{queue}}$ 是排队时延。步数从 50 降到 4 使 $N_{\\text{step}}T_{\\text{DiT}}$ 降一个数量级，此时 $T_{\\text{VAE}}$ 与 $T_{\\text{queue}}$ 在总时延中的占比上升，负载配方的重心从“压步数”转向“压排队与解码”。一个具体例子：当并发请求数超过批大小上限时，2 步档的单请求 DiT 时延已经很小，但排队时延可能反超它，此时继续降步数没有收益，应改为扩批或加副本。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-22\">二十二 · 长度分布决定批的构成</h3>\n<p>视频请求的长度分布是负载配方里最容易被忽略的变量。少步蒸馏压缩的是每帧或每段的去噪步数，但请求的总工作量仍与帧数、分辨率、段数成正比。长度分布若是窄分布（例如固定 5 秒短片），批内各请求的 DiT 前向次数接近，批调度可以做整齐的等长批，吞吐接近理论上限。长度分布若是重尾（少量长视频请求混在大量短请求中），等长批会被最长请求拖住，短请求在批内空转，有效吞吐被拉低。</p>\n<p>连续批处理在这里的作用是把“批”从静态的请求集合变成动态的 token 流：一个长请求占用的批槽位在其段间持续存在，短请求完成后立即让位给新到达的请求。对少步蒸馏而言，这意味着步数档位必须随批槽位动态重选——新进入的短请求可以走 2 步档，已在批内的长请求若已进入后段、质量要求上升，可以切到 4 步档。伪代码思路如下：</p>\n<ul>\n<li>请求到达时按 SLO 余量选初始档位：余量紧选 2 步，余量松选 8 步；</li>\n<li>每完成一个段，重算剩余时延预算，若预算仍充裕则升档，否则维持或降档；</li>\n<li>批内按档位分组做前向，同档请求共享一次 DiT 调用，避免混档导致的步索引嵌入错配；</li>\n<li>长请求的段间让出批槽位给短请求，VAE 分块解码与 DiT 前向流水重叠。</li>\n</ul>\n<p>代价在显存与带宽：混档批需要为不同步索引维护不同的中间潜变量缓冲，批内档位数越多，激活显存越碎。Blackwell 上的 tcgen05 与 TMEM 对大而整齐的 MMA 形状友好，混档批若形状不齐，MMA 利用率下降，单次前向的有效算力被浪费。因此工程判断是：档位数控制在两档以内，宁可让少数请求等待也不做三档混批。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-23\">二十三 · 并发与批大小的甜点区</h3>\n<p>少步蒸馏把单请求的 DiT 计算量压到很小，这改变了并发-吞吐曲线的形状。多步采样时，单请求计算量大，增大批大小能显著摊薄权重读取的带宽开销，吞吐随批大小上升；少步时，单请求计算量小，权重读取占比上升，批大小的边际收益提前饱和。用定性表述：存在一个甜点批大小，超过它之后每加一个请求带来的吞吐增量被激活显存与调度开销吃掉。</p>\n<p>这个甜点区由三个量共同决定：单次 DiT 前向的权重字节数、每请求的激活字节数、以及可用显存扣除 KV 类缓存与 VAE 解码缓冲后的余量。批大小上限可写成：</p>\n<div class=\"formula\">$$B_{\\max} \\approx \\frac{M_{\\text{free}} - M_{\\text{VAE}} - M_{\\text{sys}}}{A_{\\text{act}} + A_{\\text{lat}}}$$</div>\n<p>其中 $M_{\\text{free}}$ 是设备可用显存，$A_{\\text{act}}$ 是每请求激活，$A_{\\text{lat}}$ 是每请求潜变量缓冲。少步档位下 $A_{\\text{act}}$ 随步数减少而下降（中间潜变量少），$B_{\\max}$ 上升，但权重读取的固定开销不变，于是带宽成为瓶颈而非显存。具体例子：在 2 步档把批大小从 8 提到 16，DiT 前向时延可能只增加少量，但吞吐翻倍；提到 32 时，激活显存逼近上限，调度器开始拒绝请求或触发换出，尾时延恶化。负载不对时的典型症状是：平均吞吐看起来不错，但 P99 时延因少数大批的排队而飙升。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-24\">二十四 · 负载错配的三种失败形态</h3>\n<p>负载配方不对时，少步蒸馏的收益会被抵消，甚至出现比多步采样更差的服务质量。第一种失败形态是请求形态错配：把少步档位用在非流式的离线批处理上。离线批处理不关心首段时延，只关心总吞吐与质量，2 步档损失的运动多样性在这里是纯亏损，应该走 8 步档或干脆用教师模型。第二种是长度分布错配：重尾分布下用等长批，长请求拖住短请求，短请求的 SLO 被长请求的尾段拖垮，表现为短请求超时率上升而长请求正常。</p>\n<p>第三种是并发错配：并发远低于甜点批大小时，少步档位的单请求时延虽低，但设备利用率低，单位请求的功耗成本高；并发远高于甜点批大小时，排队时延主导，降步数不再改善端到端时延。这三种错配的共同点是：步数档位的选择脱离了负载的实际形状，把“降步数”当成万能杠杆。工程上应把档位选择做成闭环：以实测的排队时延与 DiT 时延之比为信号，比值高说明瓶颈在排队，应扩批或加副本；比值低说明瓶颈在计算，才值得降步数。</p>\n<p>还有一个隐蔽的失败模式与 CFG 蒸馏相关：去掉双分支后前向计算减半，但若引导强度未随档位重新校准，少步采样下条件控制减弱，文本对齐与运动幅度同时退化。负载配方若把 2 步档当作默认档位大规模铺开，这类退化会以“质量投诉”而非“时延告警”的形式出现，监控上不可见。因此档位切换必须带质量抽检，而不是只看时延指标。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-25\">二十五 · 与量化叠加时的负载约束</h3>\n<p>少步蒸馏可与 FP8/NVFP4 量化叠加，量化误差在少步下被一致性约束部分吸收。但叠加改变负载配方的边界：量化把权重与激活的字节数压低，$B_{\\max}$ 上升，甜点批大小右移；同时 NVFP4 的块缩放带来额外的元数据读取，低批大小下这部分开销占比更高。负载配方若沿用未量化时的批大小，会落在新甜点区的左侧，设备利用率不足。</p>\n<p>机制上，量化后的 MMA 形状对批的整齐度更敏感：NVFP4 的块缩放要求沿 K 维对齐，混档批若形状不齐，缩放因子的重排开销上升。工程判断是：量化叠加时优先保证批内形状一致，档位数进一步收敛到单档，用副本数而非档位多样性来吸收负载波动。代价是显存：单档大批意味着每副本的激活缓冲更大，副本数受显存限制，扩容粒度变粗。具体例子：在 GB200 NVL72 的一个节点内，量化后单副本可服务的批大小上升，但副本间的负载均衡依赖 NIXL 的传输时延，若请求路由不均，部分副本空转而部分副本排队，整体吞吐低于理论值。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-26\">二十六 · 负载配方的工程判据</h3>\n<p>把上述约束收敛成可执行的判据：第一，按请求形态分流，交互式与流式走少步档位，离线批处理走高档位或不蒸馏；第二，按长度分布选批策略，窄分布用等长批，重尾分布用连续批处理并限制批内档位数；第三，按并发水平定档位切换阈值，以排队时延与 DiT 时延之比为信号，而非以绝对并发数为信号；第四，量化叠加后重测甜点批大小，不沿用未量化的配置；第五，档位切换带质量抽检，防止 CFG 蒸馏的引导强度漂移以质量退化形式潜伏。</p>\n<p>这些判据的共同前提是：少步蒸馏压缩的是每请求的计算量，不改变请求到达的统计特性，因此负载配方的核心是把计算量的节省兑换成吞吐或时延余量，而不是无条件降步数。当负载形状与档位不匹配时，节省下来的计算量会被排队、空转或质量返工吃掉，端到端收益归零。最终落在具体机制上：步索引嵌入与批调度的耦合点，是少步蒸馏能否在真实服务里兑现时延杠杆的唯一接口，配方不对，这个接口就是断的。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-27\">二十七 · 负载配方：请求形态、长度分布与批大小的匹配边界</h3>\n<p>少步蒸馏的收益不是无条件成立的，它把 DiT 前向次数压到 2–8 步，代价是把「每步计算量」的相对权重放大：单步 DiT 前向的固定开销（权重加载、kernel launch、TMEM 分配与 tcgen05 MMA 的启动延迟）不再被 50 次迭代摊薄。因此负载配方第一条判断是批大小必须撑得住单步开销。设单步前向耗时为 <span class=\"formula\">$$T_{\\text{DiT}}(B) = \\alpha + \\beta B$$</span>，其中 α 是与批无关的启动与权重搬运成本、β 是每样本的 MMA 与访存成本，则端到端 <span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}(B)$$</span>。50 步时 α 被摊薄 50 次，4 步时只摊 4 次——小批（B 接近 1）的交互式请求在少步档位上会看到 α 占比显著上升，吞吐/时延比反而劣化。配方上应把 2 步档位留给低分辨率、短时长、单条交互请求，把 4/8 步档位与连续批处理绑定，用较大 B 把 α 压下去。</p>\n<p>第二条是长度分布。VAE 分块解码按块串行推进，潜变量序列长度决定解码段数；少步蒸馏只压缩去噪阶段，不改变解码阶段的线性成本，因此当请求的帧数或分辨率上升、解码占比超过去噪占比时，降步数的边际收益迅速衰减。判断阈值可直接比较两段耗时：若 <span class=\"formula\">$$N_{\\text{step}}T_{\\text{DiT}} &lt; T_{\\text{VAE-decode}}$$</span>，再降步数已不是端到端时延的主导杠杆，应转向解码侧的重叠与分块调度。负载配方因此要按「去噪:解码」耗时比给请求分档，而不是对所有请求统一套 4 步。</p>\n<p>第三条是并发形态。流式服务要求稳定出帧节奏，少步档位在突发并发下会因批内序列长度不齐而出现批膨胀—回退振荡：调度器为凑大批把长短请求混批，长序列拉高整批 β 项，短请求的 SLO 被拖垮。配方上应把 2 步档位与短序列桶绑定、4/8 步档位与长序列桶绑定，避免跨档混批；CFG 蒸馏去掉双分支已把前向计算减半，这部分余量应优先用于提高批大小而非继续降步数。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>适配档位</th><th>不对时的失效表现</th></tr></thead><tbody><tr><td>短时长、低分辨率、单条交互</td><td>2 步</td><td>α 占比高，时延不降反升</td></tr><tr><td>中等长度、稳定并发</td><td>4 步 + 连续批处理</td><td>批内长度不齐，SLO 抖动</td></tr><tr><td>长序列、解码占比高</td><td>8 步，重心转向解码重叠</td><td>降步数收益被解码吞掉</td></tr><tr><td>快速运动、大位移</td><td>提高步数档位</td><td>拖影与时域坍缩，多样性下降</td></tr></tbody></table>\n<p>最后一类错配是内容分布：蒸馏数据未覆盖大位移轨迹时，2 步档位在快速运动场景出现拖影，此时正确动作是升档而非加批；换基座模型而未重蒸馏、直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，会输出系统性过饱和与色彩偏移，这类错误在负载层面表现为「同一批大小下质量随请求内容漂移」，只能靠重蒸馏而非调度修复。</p>\n<h3 id=\"alg-step-distill-4step-sec-28\">二十八 · 硬件档位：按步数档位反推SM100/103的算力与显存配比</h3>\n<p>部署少步蒸馏学生的第一件事不是选卡，而是把步数档位翻译成硬件约束。端到端时延近似为 <span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</span>，其中 <span class=\"formula\">$$T_{\\text{DiT}}$$</span> 是单次DiT前向的墙钟时间，包含权重读取、激活计算与注意力。步数从50降到4，<span class=\"formula\">$$T_{\\text{DiT}}$$</span> 的权重从主导项变成唯一主导项：单步前向不再是“算得慢”，而是“读得慢”。因此硬件档位的选择标准是<strong>每步前向的权重带宽需求</strong>而非峰值FLOPS。以B200的HBM3e带宽与SM100的tcgen05 MMA为参照，一个中等规模视频DiT在FP8权重下每步前向的权重流量是固定的，步数越少，单位时间内需要反复搬运同一批权重的次数越多，带宽压力越集中。工程判断是：2步档位优先选单卡高带宽（B200/B300单机），4步档位可用单卡或2-SM MMA跨SM协作摊薄单步时延，8步档位则可以把并行维度让给序列切分而非权重切分，因为此时计算开始重新占主导。</p>\n<p>显存配比的第二个约束来自KV/潜变量缓存。少步蒸馏学生的输入是 <span class=\"formula\">$$z_t$$</span> 与步索引嵌入，中间潜变量序列长度由分辨率与分块策略决定，而非步数。这意味着步数降低不会减少激活显存，只会减少激活的<em>生命周期</em>。B300相对B200的显存容量增量应优先分配给潜变量缓冲与VAE分块解码的临时张量，而不是权重——权重已被FP8/NVFP4压到很小。一个具体例子：4步档位下，若把CFG蒸馏去掉双分支，前向计算减半，但批内并发可以翻倍，此时显存瓶颈从权重转为每请求的潜变量序列，硬件档位应从“大显存单卡”转向“多卡并行+序列切分”。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-29\">二十九 · 并行拓扑：TP/SP/PP在少步下的收益重排</h3>\n<p>少步蒸馏改变了并行维度的性价比。传统多步采样中，张量并行（TP）摊薄单步计算，收益随步数线性累积；步数降到4，TP的通信开销在每步前向中占比上升，因为每步都要做all-reduce而步间没有足够的计算掩盖通信。SM100的2-SM MMA让两个SM共享TMEM做一次更大规模的矩阵乘，等效于把TP的一部分通信转成片上协作，这是4步档位下最值得用的拓扑：把注意力的头维切分放在2-SM MMA内部完成，减少跨卡all-reduce次数。序列并行（SP）在视频DiT上更自然，因为潜变量序列长、注意力是主要开销，SP把序列切到多卡、只在注意力边界做通信，步数少时每步的通信次数与步数成正比下降，SP的摊销反而变好。</p>\n<p>流水并行（PP）在少步下基本不划算：PP的收益来自把不同层放到不同卡、用微批填满流水气泡，但4步档位下每步前向的层间依赖是串行的，气泡占比高。工程判断是：2步档位用单卡或2-SM MMA，4步档位用SP为主、TP为辅，8步档位可以引入PP但必须配合足够大的批。一个可复现的拓扑例子：GB200 NVL72机架内，4步档位把一条请求的潜变量序列按SP切到4–8张卡，权重按TP切到2卡并用2-SM MMA合并，NVLink 5承担SP的注意力边界通信；此时每步前向的通信量被压到注意力边界，而非每层all-reduce。</p>\n<p>代价要算清楚：SP的通信量与序列长度成正比，序列越长、切分越多，NVLink 5的带宽占用越高；若机架内还有分离式预填/解码的流量（见预填解码分离服务条目），SP通信会与其争抢NIXL通道。调度参数上应把SP的通信优先级与预填流量分级，避免少步解码被预填的长序列传输阻塞。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-30\">三十 · 量化方案：FP8与NVFP4在少步下的误差结构</h3>\n<p>少步蒸馏与量化叠加的核心判断是：量化误差在少步下被一致性约束部分吸收，但吸收能力有上限。多步采样中，量化误差在每一步被后续步骤部分纠正；4步档位下只剩4次纠正机会，误差累积路径变短，单步量化误差直接进入输出。因此量化方案的选择不是“越低比特越好”，而是<strong>按步数档位分配精度</strong>。8步档位可以用NVFP4压权重与激活，因为8次纠正足以吸收大部分误差；4步档位建议权重NVFP4、激活FP8，把激活的动态范围留给注意力与速度场预测；2步档位应保留FP8权重，避免NVFP4的块缩放粒度在单步大跨度预测上引入系统性偏置。</p>\n<p>具体机制：NVFP4的块缩放（block scaling）在速度场预测的尾部（大 <span class=\"formula\">$$\\Delta$$</span> 跨度）容易低估速度幅值，而少步学生的单步预测正是大跨度，误差直接表现为运动拖影。一致性约束 <span class=\"formula\">$$\\lambda\\mathcal{L}_{\\text{cons}}$$</span> 在训练时抑制过饱和，但量化是在部署时引入的，训练时的一致性约束看不到量化误差。工程做法是在蒸馏训练后期加入量化感知的展开，或在部署时对速度场输出做一次FP8的残差校正。代价是：NVFP4权重让每步前向的权重带宽减半，B200上单步时延进一步下降，但若激活也压到NVFP4，注意力输出的量化误差会在少步下放大为时域坍缩，需在蒸馏数据中覆盖大位移轨迹来补偿。</p>\n<p>一个具体例子：4步档位、CFG蒸馏去掉双分支后，条件分支只剩单分支，文本对齐依赖学生自身的条件嵌入。若文本编码器输出被量化到NVFP4，条件控制的动态范围损失会在少步下表现为运动幅度退化——这正是失败模式中“CFG蒸馏去掉双分支后引导强度未重新校准”的量化版本。因此文本侧嵌入应保持FP8或BF16，量化预算留给视觉侧权重。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-31\">三十一 · KV策略：少步下KV cache的存废与潜变量缓冲</h3>\n<p>视频扩散的KV cache与自回归语言模型的KV cache不是一回事：扩散采样每步的潜变量是同一序列的不同噪声版本，步间不共享KV。少步蒸馏把步数压到4，KV cache的复用窗口只剩4次，缓存命中率极低，继续按自回归方式维护KV cache是纯开销。工程判断是：4步及以下档位应关闭跨步KV cache，改为<strong>步内KV</strong>——每步前向内部的自注意力KV在步结束即释放，显存让给潜变量缓冲与VAE分块解码。8步档位可以保留轻量跨步缓存，但收益有限，因为一致性约束让学生每步预测的跨度不同，KV分布步间漂移大。</p>\n<p>潜变量缓冲的策略更关键。少步学生的输入 <span class=\"formula\">$$z_t$$</span> 与输出 <span class=\"formula\">$$z_{t-\\Delta}$$</span> 在4步档位下跨度大，缓冲需要容纳整段序列的中间状态。分块策略上，若VAE分块解码按块重叠（见VAE分块重叠解码条目），潜变量缓冲应按块边界对齐，避免解码时的重复搬运。显存代价：4步档位下每请求的潜变量缓冲约为序列长度×通道数×2（输入与输出双缓冲），在B300的大显存下可支撑较高并发，但若序列切分到多卡（SP），缓冲也随切分分散，跨卡同步点在步边界而非块边界。</p>\n<p>一个具体例子：流式视频服务中，请求按窗口滚动生成，每窗口4步。若沿用自回归KV cache，每窗口的缓存初始化与淘汰开销会吃掉少步带来的时延收益；改为步内KV后，每窗口的显存占用只与当前窗口的潜变量序列有关，滚动窗口的显存可以预分配复用。调度参数上应把窗口大小与步数档位绑定：2步档位用短窗口高频滚动，8步档位用长窗口低频滚动。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-32\">三十二 · 调度参数：批、步数档位与SLO的联合整定</h3>\n<p>少步蒸馏的调度核心是<strong>步数档位作为一等调度维度</strong>，而非固定配置。连续批处理（continuous batching）在扩散服务中要处理的是不同请求可能落在不同步数档位：交互式请求走2步、流式请求走4步、质量优先走8步。若把不同档位的请求混在同一批，批内每步前向的 <span class=\"formula\">$$T_{\\text{DiT}}$$</span> 由最长档位决定，短档位请求被拖慢。工程做法是按档位分桶，桶内做连续批处理，桶间用优先级调度；桶的批大小由显存与SLO反推，而非固定值。</p>\n<p>调度参数的整定顺序：先定步数档位对应的SLO（首帧时延、窗口时延），再定每档位的批大小上限，最后定桶间抢占策略。一个可复现的配置思路：4步档位、SP切4卡、FP8激活、NVFP4权重、关闭跨步KV、潜变量双缓冲按窗口预分配；批大小上限由潜变量缓冲显存除以单请求缓冲得到，调度器按窗口滚动触发，桶间以首帧时延为抢占依据。代价是：分桶会降低批的填充率，短档位桶在低负载下批小、GPU利用率下降，需用桶间弹性合并（仅在负载高时合并同档位）来平衡。</p>\n<p>失败模式的调度侧表现要写进配置：换基座模型未重蒸馏而直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出系统性过饱和与色彩偏移——调度器无法从时延指标发现这类问题，必须在配置中绑定“基座模型版本↔学生权重版本”的校验，版本不匹配时拒绝路由到少步档位、回退到多步教师。另一个失败模式是快速运动与大位移场景的拖影，调度侧可通过请求元数据（运动幅度估计）把这类请求路由到8步档位，用步数换质量，这是步数档位作为调度维度的直接价值。</p>\n<p>容量规划上，步数从50降到4使DiT前向时延降一个数量级，单卡可支撑的并发请求数随之上升，但VAE分块解码的时延不随步数下降，会成为新的端到端瓶颈。配置中应把VAE解码的并行度与DiT的并行拓扑解耦：DiT用SP切序列，VAE解码用独立的解码卡或分块流水，避免解码阻塞DiT的步边界。最终落在具体机制上：调度器以步边界为同步点、以窗口为调度单位、以档位为分桶键，三者绑定后少步蒸馏的时延收益才能完整传递到端到端SLO。</p>\n\n\n<h3 id=\"alg-step-distill-4step-sec-33\">三十三 · 档位切换的失效面与代价核算</h3>\n<p>部署配方最容易犯的错，是把 2/4/8 步当成三个可自由滑动的旋钮。实际上档位切换改变的是学生网络的步索引嵌入所对应的有效时间跨度 Δ：4 步档下 Δ 约为教师轨迹的 1/4 段，2 步档下 Δ 翻倍，学生单步要预测的去噪增量跨度随之变大，一致性约束在训练时覆盖的展开长度若不匹配，过饱和会先在快速运动段出现。因此档位不是运行时参数，而是训练时就绑定的离散集合——换档等于换学生权重，或至少换一套步索引嵌入。工程上应把档位与请求的 SLO 类别硬绑定：交互式首帧走 2 步档抢首包，流式续帧走 4 步档保运动连续性，8 步档留给离线补帧或大位移场景兜底，而不是让调度器按瞬时负载随意升降。</p>\n<p>代价核算要落在端到端而非 DiT 前向。少步蒸馏把 DiT 前向压下一个数量级，但 VAE 分块解码的像素域开销不随步数缩小，CFG 蒸馏去掉双分支后前向计算减半、显存占用也减半，于是瓶颈从去噪段迁移到解码段与潜变量搬运段。此时端到端时延可写成 <span class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}T_{\\text{DiT}}+T_{\\text{VAE}}+T_{\\text{xfer}}$$</span>，继续压步数的边际收益迅速衰减——从 4 步降到 2 步只省下两段 DiT 前向，却要付出运动多样性下降的代价。判断档位是否值得再降，应看 <span class=\"formula\">$$N_{\\text{step}}T_{\\text{DiT}}$$</span> 是否仍占 <span class=\"formula\">$$T_{\\text{e2e}}$$</span> 的主导份额；一旦解码与传输过半，就该转去优化分块重叠与显存驻留，而不是继续砍步数。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测征兆</th><th>系统侧代价</th></tr></thead><tbody><tr><td>换基座未重蒸馏</td><td>系统性过饱和、色彩偏移</td><td>步索引嵌入与教师轨迹分布失配，整批请求返工</td></tr><tr><td>CFG 引导强度未重校准</td><td>文本对齐与运动幅度同时退化</td><td>需回退双分支，前向计算与显存翻倍</td></tr><tr><td>大位移轨迹未覆盖</td><td>快速运动拖影、时域坍缩</td><td>被迫升档至 8 步，时延杠杆失效</td></tr></tbody></table>\n<p>量化叠加的边界同样要写进配方。FP8/NVFP4 的误差在少步下被一致性约束部分吸收，但这一吸收有前提：量化校准集必须覆盖学生实际展开的 Δ 跨度，否则 2 步档下被放大的量化偏差会直接表现为首帧色偏。可行的工程判断是量化档位与步数档位联合标定——4 步档配 FP8 作为默认组合，2 步档仅在 NVFP4 校准充分时启用，8 步档保留高精度以兜底大位移场景。换基座模型必须重蒸馏并重跑这套联合标定，直接复用旧学生权重是本配方最典型的系统性失败。</p>\n<h3 id=\"alg-step-distill-4step-sec-34\">三十四 · 少步之后的时延结构：DiT 不再是全部</h3>\n<p>把步数从 50 压到 4，<span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</span> 这条线性关系立刻把瓶颈从去噪循环挪到了别处。单步 DiT 前向在 Blackwell 上被 tcgen05 与 NVFP4/FP8 进一步压缩后，端到端时延里 VAE 分块解码、潜变量搬运、请求调度与首帧同步的占比显著上升。工程上要盯的不是“DiT 快了多少倍”，而是少步档位下各段耗时的重新排序：4 步时 DiT 只占端到端的一小段，VAE 解码与跨卡潜变量传输反而成为尾延迟的主项。以 2/4/8 三档为例，2 步档把 DiT 压到极短，此时若 VAE 分块解码仍按 50 步时代的串行节奏排布，端到端时延几乎不随步数下降——这就是“规模上去以后哪里先崩”的第一个答案：先崩的不是算力，是没跟着改的解码与传输路径。</p>\n<p>代价的直接体现是显存驻留时间。少步意味着单请求在 DiT 侧的激活生命周期变短，但 VAE 解码侧的潜变量张量与分块缓冲仍按原尺寸驻留；连续批处理下，解码阶段占用 SM 与显存的时长相对变长，批内请求的完成时间被解码段拉平。吞吐上，单位时间完成的请求数不再由 DiT 前向决定，而由“解码吞吐 × 可并行解码块数”决定。判断依据很具体：把 4 步档的端到端耗时拆成 DiT、VAE、传输三段，若 VAE 段超过 DiT 段，则继续压步数对 SLO 无收益，应转向解码侧的分块并行与重叠。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-35\">三十五 · 显存与带宽：潜变量搬运成为主账</h3>\n<p>少步蒸馏不改变潜变量张量的形状，只改变产生它的迭代次数，因此显存账本里“每请求潜变量 + 分块缓冲 + KV 类中间态”的静态占用不变，变的是周转率。4 步档下同一张卡的显存带宽被更频繁地用于潜变量的读写与跨卡搬运，而非权重流式加载。Blackwell 的 HBM 带宽与 NVLink 5 提供了余量，但带宽账要按“每生成一秒视频需要搬运多少潜变量字节”来算：步数减少使每请求的 DiT 读写次数下降，却使单位时间内并发请求数上升，总带宽需求未必下降。这是少步蒸馏在容量规划上最容易被误判的一点——单请求变快不等于集群带宽变省。</p>\n<p>具体机制上，CFG 蒸馏去掉双分支直接把单步前向的激活与权重读取减半，这是少步档位下最干净的带宽节省项；它与 NVFP4 量化叠加时，权重带宽按位宽比例下降，但潜变量仍以较高精度在卡间流动，于是瓶颈从权重侧转到激活侧。工程判断：在 2 步档、高并发流式场景下，若激活搬运占 NVLink 流量主导，应优先做潜变量的低精度传输与分块流水，而不是继续压权重位宽。显存侧的失败模式是分块缓冲与并发请求数相乘后触顶，表现为批调度被迫缩小批、尾延迟抬升。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-36\">三十六 · 通信：分离式部署下少步放大同步开销</h3>\n<p>预填/解码分离与 NVL72 机架内并行是 Blackwell 推理的常规形态，少步蒸馏在此结构下改变了通信比例。50 步时每请求有大量 DiT 前向可用来掩盖跨卡同步；4 步时前向次数少，每次前向后的集合通信（张量并行 all-reduce、专家并行 all-to-all）在端到端时延中的占比上升。若并行度不变，通信延迟不再被计算掩盖，尾延迟由最慢的那次集合通信决定。机制上，2-SM MMA 与 TMEM 的利用要求 tile 足够大，少步下每步的计算量并未减少，但步间没有足够的独立工作去填通信空隙，流水线气泡显性化。</p>\n<p>代价可定性表述为：步数越低，通信在端到端时延中的份额越高，规模越大越明显。具体例子是 NVL72 内一个跨多卡的 4 步请求：若每步后都有一次全卡归约，4 次归约的固定开销在 50 步时被摊薄到可忽略，在 4 步时则与 DiT 计算同量级。应对不是加步数，而是把并行切分与少步档位对齐——低步档优先用更小的并行域配合更大批，把通信次数换成批内并行；高步档再放开并行度。NIXL 类传输在分离式部署中承担潜变量与 KV 的跨节点搬运，少步下其调用频次随请求数上升，需按“每请求传输次数 × 并发数”做容量预留。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-37\">三十七 · 功耗与热：少步不等于省电</h3>\n<p>少步蒸馏降低的是单请求的 DiT 能耗，但吞吐上升会把集群功耗拉回甚至推高。原因是解码段与传输段的功耗占比上升，而这些段落并不随步数线性下降；同时高并发下 SM 长期处于高占用，功耗曲线更平。工程上要区分“每请求能耗”与“每视频秒能耗”：前者随步数下降明显，后者取决于解码与传输的效率。Blackwell 的功耗管理在批调度层面体现为频率与占用的折中，少步档下若批被解码段阻塞，SM 空转与高频并存，能效反而变差。</p>\n<p>具体机制是把 VAE 分块解码与 DiT 前向做流水重叠，使 SM 在等待解码时仍有可执行工作，压平功耗曲线的同时降低尾延迟。判断依据是单位时间内 SM 活跃周期与解码阻塞周期的比例；若阻塞周期占比高，说明批调度没有按少步档位重排，需把解码块数与并发请求数解耦。功耗侧的失败模式是 2 步档下为追 SLO 而无限加批，导致显存与带宽触顶后批被强制切小，功耗与尾延迟同时恶化。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-38\">三十八 · 尾延迟：规模上去后先崩的是调度粒度</h3>\n<p>少步档位的尾延迟来源与均值不同。均值由 DiT 前向与解码平均耗时决定，尾延迟由最慢请求的排队、最慢分块的解码、以及最慢一次集合通信叠加而成。规模上去后，连续批处理里长短请求混批，少步请求本应快速完成，却被同批内长解码请求拖住，形成“快请求等慢解码”的尾延迟。机制上，步索引嵌入让学生网络按档位工作，但调度器若仍按统一批处理，档位差异无法转化为完成时间差异。</p>\n<p>工程做法是按步数档位分桶调度：2 步档请求进短批、优先出队，4/8 步档进长批；解码段按分块粒度独立排队，使 DiT 完成即释放，不必等整段 VAE 解码结束。代价是分桶带来批规模下降与显存碎片，需在桶数与批大小间做折中。具体例子是流式服务中首帧请求走 2 步档短批、后续帧走 4 步档长批，若不分桶，首帧尾延迟被后续帧解码拖长，交互体验直接受损。规模上限在此显现：当并发请求数超过分桶可维持的最小批规模时，尾延迟随规模非线性上升，这是少步蒸馏在集群层面最先崩的位置。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-39\">三十九 · 失败模式与工程判断的落点</h3>\n<p>三类失败模式在系统层面各有对应代价。少步损失运动多样性、快速运动出现拖影，对应的是为保质量而提高步数档位，直接抬升 DiT 段时延与功耗；换基座未重蒸馏导致步索引嵌入与教师轨迹分布不匹配、输出系统性过饱和与色彩偏移，对应的是重蒸馏管线的时间成本与上线窗口冲突；CFG 蒸馏后引导强度未重校准导致条件控制减弱，对应的是为补质量而恢复双分支，前向计算翻倍、带宽节省项归零。三者都不是单点 bug，而是容量规划里必须预留的档位切换余量。</p>\n<p>落点在调度器的一个具体判断：按 SLO 把请求映射到 2/4/8 步档，同时按档位决定并行域大小、批桶与解码块数，使 <span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</span> 之外的 VAE、传输、通信三段不成为新的主导项。规模上去后先崩的顺序是：解码与传输的串行路径、跨卡集合通信的固定开销、分桶调度失效后的尾延迟；算力本身在 Blackwell 上并非首崩点。工程判断因此是——少步蒸馏的吞吐收益只有在解码流水、通信切分与分桶调度同步改造后才能兑现，否则步数下降只换来均值好看、尾部恶化。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-40\">四十 · 少步蒸馏的规模拐点：从 DiT 前向到 VAE 解码的代价迁移</h3>\n<p>把步数从 50 压到 4，<span class=\"inline-math\">$T_{\\text{gen}}\\approx N_{\\text{step}}T_{\\text{DiT}}$</span> 这一线性关系立刻把瓶颈从去噪循环推走：DiT 前向时延降一个数量级后，端到端时延的构成发生结构性迁移。原先 50 步下 DiT 占绝对主导，VAE 分块解码只是尾部开销；到 4 步时，单次 DiT 前向（含 CFG 蒸馏后已减半的双分支计算）与单块 VAE 解码的耗时进入同一量级，分块解码的串行依赖、潜变量搬运与像素域写回开始主导尾延迟。规模上去以后先崩的往往不是 DiT 算力，而是解码侧的显存带宽与块间流水：每块解码需读入整段潜变量切片、写出高分辨率像素张量，带宽压力随分辨率与帧数超线性增长，而 DiT 侧因步数压缩反而空出了 SM 与 Tensor Core 的余量。工程判断是：少步档位必须与 VAE 分块重叠解码同步调参，否则步数收益会被解码串行化吃掉。</p>\n<p>步数档位（2/4/8）在容量规划上不是三个独立模型，而是同一学生权重配不同步索引嵌入的推理路径，因此显存占用基本恒定，差异体现在计算与通信的配比。8 步档位下 DiT 前向重新成为主项，2 步档位下每步预测的时间跨度更大、速度场幅值更高，NVFP4/FP8 量化的相对误差被放大——一致性约束在训练时吸收了部分量化误差，但吸收能力随步数减少而衰减，2 步档位对量化校准集的要求明显高于 8 步。批调度层面，少步使单请求占用 SM 的时间片变短，连续批处理的批拼装窗口随之收窄，固定批大小下 GPU 利用率对到达率的抖动更敏感；流式服务中若按帧粒度拼批，批内步数档位不一致会强制取最大步数，等于把 2 步请求拖回 8 步的时延。可行做法是按档位分桶排队，桶内再拼批。</p>\n<p>通信代价在分离式预填/解码与多卡并行下被少步蒸馏重新定价。步数压缩使单次前向的计算通信比下降，张量并行下每步的 All-Reduce 延迟不再被计算充分掩盖，2 步档位尤其明显：两次前向各夹一次集合通信，通信延迟在端到端时延中的占比从边缘项升为可观项。NVL72 域内 NVLink 5 的高带宽能压住这部分，但跨节点扩展时 NCCL 的拓扑感知与 NIXL 的传输路径选择直接决定尾延迟。功耗侧，少步把 DiT 的持续高功耗窗口缩短，却把 VAE 解码的功耗占比抬高，机架级功率预算需按解码峰值而非去噪均值来配。失效条件集中在两处：换基座模型未重蒸馏而直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出出现系统性过饱和与色彩偏移；CFG 蒸馏去掉双分支后引导强度未重新校准，少步下文本对齐与运动幅度同时退化。快速运动与大位移场景的多样性上限受教师轨迹覆盖范围约束，需在蒸馏数据中覆盖大位移轨迹或临时提高步数档位，这是少步方案在规模上最先触到的质量边界。</p>\n<h3 id=\"alg-step-distill-4step-sec-41\">四十一 · 精度漂移：少步放大数值误差的三条路径</h3>\n<p>少步蒸馏把学生前向次数压到 2/4/8，误差不再被多步迭代平均掉，而是被单步的大时间跨度直接放大。诊断时要区分三条独立路径：其一是速度场回归误差，学生一次预测 <span class=\"inline\">Δ</span> 跨度的增量，若速度场在 <span class=\"inline\">z_t</span> 附近偏差 <span class=\"inline\">ε</span>，则潜变量误差近似为 <span class=\"inline\">Δ·ε</span>，步数越少 <span class=\"inline\">Δ</span> 越大，误差线性放大；其二是量化误差，FP8/NVFP4 下权重与激活的舍入误差在少步下缺少后续步骤的自我修正，一致性约束只能部分吸收；其三是 CFG 蒸馏后的引导强度失配，去掉双分支后若未重新校准，条件控制减弱表现为文本对齐退化与运动幅度收缩同时出现。</p>\n<div class=\"formula\">$$\\lVert \\hat{z}_{t-\\Delta}-z_{t-\\Delta}\\rVert \\approx \\Delta\\,\\lVert v_\\theta(z_t,t)-v_{\\text{tea}}(z_t,t)\\rVert + \\Delta\\,\\lVert \\delta_q\\rVert$$</div>\n<p>工程上把这三条路径做成可分离的监控量：固定一批校准 prompt 与固定种子，分别跑 8 步、4 步、2 步三档，记录与教师 50 步输出的潜变量余弦距离、帧间光流幅值分布、以及文本-视频对齐打分。若 8 步正常而 2 步余弦距离骤增，是速度场回归问题；若三档同时偏移且量化开关切换时跳变，是量化路径；若仅条件相关指标下降而运动幅值同步缩小，是 CFG 校准问题。代价上，这套校准集每次全档位跑一遍要占用与线上同规格的 DiT 前向，属于纯开销，必须放在离线或低峰时段，且校准集规模要控制在能覆盖大位移轨迹的最小集合，否则显存与时间成本会挤占线上容量。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-42\">四十二 · OOM：潜变量、KV 与分块解码的叠加账</h3>\n<p>少步蒸馏本身不增加显存，但部署配方里三件事叠加会触发 OOM：长视频的潜变量张量随分辨率与帧数线性增长；VAE 分块解码的中间激活在重叠区翻倍；若同时开连续批处理，多请求的潜变量与解码缓冲并发驻留。诊断顺序应是先看单请求峰值，再看批内并发峰值。单请求峰值可用分块解码的块大小与重叠帧数直接估算，重叠区激活约为非重叠区的两倍，块越小峰值越低但重叠开销占比越高。批内并发则要看调度器是否把解码阶段与去噪阶段混跑在同一显存池。</p>\n<p>具体例子：一个 4 步档位的流式请求，去噪阶段潜变量占用稳定，但 VAE 分块解码在最后几块出现尖峰，若此时调度器又塞入新请求的去噪前向，峰值叠加即 OOM。处置手段是给解码阶段设独立显存配额或串行化闸门，让解码不与新请求的去噪并发；另一种是把解码块大小按剩余显存动态下调，代价是重叠区比例上升、解码吞吐下降。监控上要采集每阶段的显存水位而非仅看进程总峰值，否则无法定位是去噪还是解码触发。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-43\">四十三 · 批抖动与路由不均：步数档位打散批的代价</h3>\n<p>按 SLO 在 2/4/8 步间切换意味着同一批内请求的 DiT 前向次数不同。连续批处理按 token 或按请求聚合时，步数不一致会让批的有效计算量抖动：4 步请求与 8 步请求混批，短请求提前完成后批内剩余请求的计算密度下降，GPU 利用率出现锯齿。更隐蔽的是路由不均——若调度器按请求到达顺序而非按步数档位分组，同一时间窗口内 2 步请求扎堆会让 DiT 单元空转等解码，而 8 步请求扎堆则让解码单元空转。诊断指标是批内步数方差与各阶段 SM 占用率的时序相关性：方差高且占用率抖动同步，即为批抖动。</p>\n<ul>\n<li>按步数档位做路由分组，同档位请求优先同批，牺牲少量排队公平换计算密度稳定。</li>\n<li>给每档位设独立的批上限与超时阈值，避免 8 步请求长期占据批位拖慢 2 步请求的尾延迟。</li>\n<li>监控批内步数方差、各阶段占用率、以及每档位的 P99 时延，三者联动判断是抖动还是容量不足。</li>\n</ul>\n<p>代价是分组路由降低了批的填充灵活性，低峰期可能出现档位内批未满而等待，吞吐略降；但换来的是时延可预测性，对流式服务而言这个交换通常划算。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-44\">四十四 · 尾延迟尖刺：解码重叠区与重蒸馏切换</h3>\n<p>尾延迟尖刺有两个高频来源。其一是 VAE 分块解码的重叠区：重叠帧的激活与计算量高于非重叠块，若块调度不均，最后一块常成为长尾；叠加少步蒸馏后去噪阶段变短，解码占比上升，尖刺更显眼。其二是换基座模型未重蒸馏而直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出出现系统性过饱和与色彩偏移，同时因为学生速度场偏离，部分请求会触发重试或降档重跑，表现为尾延迟突增且伴随质量告警。</p>\n<p>诊断上把尾延迟按阶段拆解：去噪、解码、传输各自 P99 与 P50 的比值。若解码阶段比值显著高于去噪，优先查块调度与重叠区；若去噪阶段比值高且伴随输出质量指标下滑，查学生权重与基座是否匹配、步索引嵌入是否越界。处置上，解码侧用块级流水让重叠区计算与下一块的非重叠计算交错，削平尖刺；模型侧建立基座版本与学生权重的绑定校验，版本不一致直接拒绝加载而非静默降级。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-45\">四十五 · 监控与回滚：把档位切换做成可逆操作</h3>\n<p>监控体系要围绕步数档位组织，而不是围绕单一模型实例。每个档位独立采集：输出质量代理指标（与教师轨迹的余弦距离、光流幅值分布、文本对齐打分）、时延分位、显存水位、批内步数方差。告警阈值按档位分别设定，2 步档位对质量指标更敏感，8 步档位对时延更敏感。回滚的最小单位是档位而非整机：某档位质量指标越界时，把该档位流量切到相邻更高步数档位，代价是时延上升但质量恢复；若尖刺来自解码，则回滚解码块大小与重叠参数而非动模型。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要监控量</th><th>回滚动作</th><th>代价</th></tr></thead><tbody><tr><td>精度漂移（速度场/量化/CFG）</td><td>与教师轨迹余弦距离、对齐打分</td><td>档位升步或关闭量化路径</td><td>时延上升、显存增加</td></tr><tr><td>OOM</td><td>分阶段显存水位</td><td>解码块缩小、解码与新请求串行</td><td>解码吞吐下降</td></tr><tr><td>批抖动/路由不均</td><td>批内步数方差、占用率</td><td>恢复按档位分组路由</td><td>批填充灵活性下降</td></tr><tr><td>尾延迟尖刺</td><td>各阶段 P99/P50</td><td>块级流水、基座版本校验</td><td>实现复杂度、拒绝加载</td></tr></tbody></table>\n<p>回滚必须预置而非临场构造：档位映射表、量化开关、解码块参数都要能在不改模型权重的前提下热切换，且切换后要有一次校准集验证再放量。若换基座模型，重蒸馏是硬门槛——学生权重与步索引嵌入必须随基座重训，直接复用会同时触发精度与尾延迟两类失败，此时唯一正确的回滚是回退到旧基座加旧学生的整组版本，而不是混搭。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-46\">四十六 · 少步蒸馏的失效边界与线上诊断：从过饱和到批抖动</h3>\n<p>少步蒸馏把采样步数压到 2/4/8 档位后，系统的主要风险从“算得慢”转成“算得不对且不易察觉”。三类失效需要分开归因。第一类是精度类：CFG 蒸馏去掉双分支后，引导强度若未重新校准，少步采样下条件控制减弱，表现为文本对齐退化与运动幅度同时塌缩；若换基座模型而未重蒸馏、直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出会出现系统性过饱和与色彩偏移——这类错误在单帧上像“风格化”，在视频上则是整段偏色，靠人眼抽检极易漏过。第二类是运动类：少步蒸馏损失运动多样性，快速运动与大位移场景出现拖影与时域坍缩，本质是学生在大 Δ 跨度上把速度场平滑成了均值场。第三类是系统类：OOM、批抖动、路由不均与尾延迟尖刺，它们与蒸馏本身无直接因果，但少步档位把单请求 DiT 前向压短后，VAE 分块解码与潜变量搬运在端到端时延中的占比上升，瓶颈发生迁移，原先按 50 步标定的容量模型全部失准。</p>\n<p>诊断要落到可观测量上。对精度类失效，监控对象不是像素而是潜变量统计量：按步索引分桶统计学生输出速度场的范数与方向方差，与教师离线轨迹的同桶统计做对比，偏差持续超阈值即触发重蒸馏或回滚档位。对运动类失效，用光流幅值分布与帧间潜变量差分的相关性做在线探针，拖影段的典型特征是光流大而潜变量差分小，二者脱钩。系统侧则要把端到端时延拆成可加项：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}+T_{\\text{VAE}}+T_{\\text{queue}},\\qquad \\text{尾延迟由 } \\max(T_{\\text{VAE}}^{\\text{chunk}},\\,T_{\\text{queue}}) \\text{ 主导}$$</div>\n<p>步数从 50 降到 4 使 DiT 项降一个数量级后，$T_{\\text{VAE}}$ 与排队项成为尾延迟尖刺的主因，此时继续压步数收益递减，而批抖动会被放大：连续批处理中一个 8 步档的长请求混入 2 步档批次，会拉长整批的 DiT 迭代节拍，形成周期性尖刺。工程判断是给步数档位做批次隔离而非混批，并按档位分别设 SLO 与超时。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测量</th><th>处置</th></tr></thead><tbody><tr><td>过饱和/色彩偏移</td><td>潜变量均值与方差按步索引分桶偏移</td><td>重蒸馏或回滚至上一学生权重</td></tr><tr><td>拖影/时域坍缩</td><td>光流幅值与潜变量差分脱钩</td><td>提高步数档位、补大位移轨迹数据</td></tr><tr><td>批抖动/尾尖刺</td><td>批迭代节拍方差、VAE 分块耗时</td><td>档位隔离、VAE 分块与 DiT 重叠</td></tr><tr><td>OOM</td><td>峰值激活与 KV/潜变量驻留</td><td>降档、缩批、分块解码</td></tr></tbody></table>\n<p>回滚策略必须按档位而非整模型粒度设计：学生权重、CFG 引导强度、步数档位三者构成一个耦合配置，任一变更都要能独立回退到已验证组合，且回滚后需重跑离线轨迹对齐检查而非仅看端到端时延。少步蒸馏与 FP8/NVFP4 量化叠加时，量化误差被一致性约束部分吸收，但这也意味着精度退化会以“看起来还行”的方式潜伏，监控阈值应偏向敏感而非宽松。边界在于：快速运动与大位移场景的多样性上限受教师轨迹覆盖范围约束，蒸馏数据未覆盖的位移尺度无法靠调档弥补；换基座模型必须重蒸馏，学生权重不可跨基座复用。</p>\n<h3 id=\"alg-step-distill-4step-sec-47\">四十七 · 同族算法的坐标：三条正交的加速轴</h3>\n<p>把少步蒸馏放回它所在的算法族里看，视频扩散推理的加速手段可以拆成三条彼此正交的轴：<strong>时间轴</strong>（减少去噪迭代次数）、<strong>空间/通道轴</strong>（降低单次前向的算术强度，如低比特量化、稀疏注意力）、<strong>状态轴</strong>（复用或压缩跨步中间状态，如轨迹缓存、KV 量化）。少步蒸馏只动时间轴——它把 <span class=\"inline-math\">$N_{\\text{step}}$</span> 从 50 压到 2/4/8，而 <span class=\"inline-math\">$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$</span> 是线性关系，所以它是唯一能给出数量级时延收益的杠杆；量化与稀疏只改 <span class=\"inline-math\">$T_{\\text{DiT}}$</span> 的系数，缓存复用改的是有效步数而非名义步数。理解这一点，选型的第一问就不是\"哪个算法更好\"，而是\"当前 SLO 缺口落在哪条轴上\"。</p>\n<p>三条轴的可叠加性并不对称。蒸馏与量化可以叠加：一致性约束在少步展开上施加平滑性，量化误差被部分吸收，代价是低比特下速度场的尾部被削平，快速运动更易拖影。蒸馏与缓存复用则存在语义冲突——缓存复用假设相邻步的中间激活高度相关，而少步蒸馏恰恰让每一步跨越更大的时间间隔 <span class=\"inline-math\">$\\Delta$</span>，步间相关性下降，缓存命中率与复用收益同步缩水。工程判断是：一旦步数降到 4 以下，轨迹缓存的边际收益应重新测量，而不是沿用 50 步配置下的命中率假设。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-48\">四十八 · 决策表：按 SLO 缺口与场景形态选型</h3>\n<p>下表把同族算法按\"主攻轴—典型收益形态—主要代价—适用条件\"四列对齐。收益一律定性表述，因为具体倍数取决于基座、分辨率与批形态，任何脱离上下文的数字都不可信。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法族</th><th>主攻轴</th><th>收益形态</th><th>主要代价</th><th>适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>少步蒸馏（本条目）</td><td>时间轴，压 <span class=\"inline-math\">$N_{\\text{step}}$</span></td><td>端到端时延随步数线性下降，50→4 为数量级</td><td>运动多样性损失、需教师轨迹与重蒸馏</td><td>交互式/流式，SLO 缺口在采样步数</td></tr>\n<tr><td>低比特量化（NVFP4/FP8）</td><td>算术强度，压 <span class=\"inline-math\">$T_{\\text{DiT}}$</span></td><td>单步前向更快、显存占用更低</td><td>数值误差，需校准</td><td>显存或算力受限，步数已较低</td></tr>\n<tr><td>稀疏时空注意力</td><td>算术强度，压注意力项</td><td>长序列下注意力开销下降</td><td>稀疏模式与运动不匹配时质量退化</td><td>高分辨率、长时长，注意力成瓶颈</td></tr>\n<tr><td>轨迹感知缓存复用</td><td>状态轴，复用中间激活</td><td>有效步数下降，无需重训</td><td>步间相关性假设，少步下收益缩水</td><td>步数仍较高、无重训预算</td></tr>\n<tr><td>VAE 分块重叠解码</td><td>像素域解码阶段</td><td>解码显存峰值下降、可流式出帧</td><td>重叠区重复计算</td><td>高分辨率输出、解码成瓶颈</td></tr>\n<tr><td>投机解码（自回归视频）</td><td>时间轴，跨 token 并行验证</td><td>接受率高时等效步数下降</td><td>草稿模型开销、接受率不稳</td><td>自回归式视频生成器</td></tr>\n</tbody>\n</table>\n<p>读表的方法是自上而下排除：若端到端剖析显示 DiT 前向占总时延的主导份额且步数为 50，则蒸馏是首选，量化是叠加项；若前向已快而解码阶段显存峰值卡住并发，则问题在 VAE 侧，蒸馏无用；若不允许重训（基座频繁更换、无教师轨迹管线），则只能走缓存复用与量化，接受较小的收益上限。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-49\">四十九 · 选型的量化判据：把 SLO 缺口拆到项</h3>\n<p>选型不应凭直觉，而应把端到端时延写成可分解的预算式，逐项对照各算法的作用位置：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx \\underbrace{N_{\\text{step}}\\,T_{\\text{DiT}}(B)}_{\\text{采样}}+\\underbrace{T_{\\text{VAE}}}_{\\text{解码}}+\\underbrace{T_{\\text{queue}}}_{\\text{调度}}$$</div>\n<p>其中 <span class=\"inline-math\">$T_{\\text{DiT}}(B)$</span> 随批大小 <span class=\"inline-math\">$B$</span> 变化而非线性——Blackwell 上大 batch 摊薄权重带宽后单请求摊销成本下降，这使\"降步数\"与\"提 batch\"之间存在替代关系：把步数从 50 降到 4 相当于把每请求的 DiT 调用次数降到 1/12 左右，调度器因此可以把释放出的算力换成更大的批，吞吐与时延同时改善；反之若显存已被 KV/激活占满、批上不去，则量化与分块解码才是解锁并发的钥匙。判据可以写成：先测三项占比，若采样项占比超过一半且 <span class=\"inline-math\">$N_{\\text{step}}$</span> 高，选蒸馏；若采样项已低而解码项或排队项抬头，选 VAE 分块与调度侧手段。</p>\n<p>第二个判据是<strong>质量预算的分配位置</strong>。蒸馏把误差集中施加在速度场的低频运动分量上（多样性、拖影），量化把误差施加在高频细节与数值尾部，缓存复用把误差施加在跨步一致性上。三者失败模式不同，诊断手段也不同：蒸馏失败表现为大位移拖影与时域坍缩，量化失败表现为色彩偏移与纹理噪声，缓存失败表现为帧间抖动。选型时应优先选择失败模式与业务容忍度匹配的算法——体育与动作类内容对拖影零容忍，应保留较高步数档位（4 或 8）而非压到 2；静态访谈类内容可压到 2 步并用 4 步做兜底。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-50\">五十 · 组合顺序与叠加代价</h3>\n<p>多算法叠加时的顺序不是任意的。推荐顺序为：<strong>先蒸馏定步数档位，再量化定数值格式，最后按剩余预算决定是否启用缓存复用</strong>。理由是蒸馏改变学生权重与步索引嵌入，量化校准必须在蒸馏后的学生上重新做——在教师上校准的 scale 迁移到少步学生上会失配，因为少步下激活分布更集中、尾部更短。同理，缓存复用的命中率阈值应在最终步数下重测，不能沿用高步数配置。</p>\n<p>叠加的代价需要显式记账。以 4 步档位 + CFG 蒸馏为例：CFG 蒸馏去掉双分支使单步前向计算减半，这是与降步数相乘的收益；但引导强度需重新校准，否则少步下条件控制减弱，文本对齐与运动幅度同时退化——这是叠加引入的新失败模式，不属于任何单一算法。再叠加 NVFP4 量化时，一致性约束吸收部分量化误差，但速度场尾部被削平会放大拖影，因此量化位宽的选择应与步数档位联动：2 步档位下不宜同时使用最激进位宽，否则两类误差在同一运动分量上叠加。显存侧则相反：蒸馏不改变激活峰值（每步仍要存一份潜变量与注意力工作集），量化才真正降低权重与激活占用，所以\"显存不够\"这一症状指向量化与分块解码，而非蒸馏。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-51\">五十一 · 适用条件与不适用清单</h3>\n<p>把适用条件写成可核对的清单，比写\"适合时延敏感场景\"有用得多。满足以下全部条件时，少步蒸馏是首选：端到端剖析中采样项占主导；<span class=\"inline-math\">$N_{\\text{step}}$</span> 仍处于高位（数十步量级）；存在可复现的教师采样轨迹用于监督；基座模型在服务周期内稳定，重蒸馏成本可摊销；业务对快速运动与大位移的多样性损失有明确容忍度或可通过提高档位兜底。任一条件不满足，就应把预算转向其他轴。</p>\n<ul>\n<li><strong>不适用一：基座频繁更换。</strong>换基座未重蒸馏而直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出出现系统性过饱和与色彩偏移——这不是调参能修的，只能重蒸馏。</li>\n<li><strong>不适用二：大位移场景占主导。</strong>教师轨迹覆盖范围决定学生多样性上限，蒸馏数据未覆盖大位移轨迹时，提高步数档位也只是缓解而非解决。</li>\n<li><strong>不适用三：瓶颈在解码或调度。</strong>此时降步数只缩短采样项，端到端收益被 Amdahl 定律压缩，应优先 VAE 分块重叠解码与批调度。</li>\n<li><strong>不适用四：无重训管线且要求零质量回归。</strong>缓存复用与量化是无需重训的选项，收益较小但风险可控。</li>\n</ul>\n<p>最后一条工程判断落在档位切换的实现上：2/4/8 步档位应在同一学生权重下通过步索引嵌入切换，而非维护三套权重——后者使显存与加载成本翻倍，且档位间质量不一致难以诊断。档位切换的代价是每档需独立校准 CFG 引导强度与量化 scale，这部分校准工作量应计入部署预算，而不是当作蒸馏训练完成后的免费副产品。</p>\n\n<h3 id=\"alg-step-distill-4step-sec-52\">五十二 · 边界判定：蒸馏、缓存复用与解码侧优化何时互斥</h3>\n<p>把少步蒸馏放进整条视频生成流水线看，它只压缩去噪采样阶段，与VAE分块重叠解码作用于像素域解码是两个正交的时延来源。工程上常见的误判是把两者当成替代关系：当DiT前向仍占端到端时延主导（<span class=\"formula\">$$T_{\\text{gen}}\\approx N_{\\text{step}}\\,T_{\\text{DiT}}$$</span>中<span class=\"formula\">$$N_{\\text{step}}$$</span>项远大于解码项）时，先做步数压缩收益最大；反之若步数已压到2–4步、解码成为瓶颈，再压步数只会放大运动失真而不缩短时延。与缓存复用类方法的差别在于作用对象：缓存复用不改权重，靠跨步复用中间激活换取加速，其失效条件是相邻步潜变量差异大——恰是快速运动场景；蒸馏改的是学生权重，失效条件则是教师轨迹覆盖不足。两者可叠加，但缓存复用在少步下的复用窗口变窄，收益被步数压缩本身吃掉，需按实际步数档位重新评估。</p>\n<p>决策表可按三个判据收敛：时延敏感度、运动复杂度、基座模型稳定性。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>选少步蒸馏</th><th>选缓存复用</th><th>选解码侧优化</th></tr></thead><tbody><tr><td>端到端时延被采样步数主导</td><td>是，首选</td><td>否</td><td>否</td></tr><tr><td>相邻步潜变量差异小、运动平缓</td><td>可叠加</td><td>是，首选</td><td>否</td></tr><tr><td>解码占端到端时延显著份额</td><td>否</td><td>否</td><td>是，首选</td></tr><tr><td>基座模型频繁更换</td><td>慎用（需重蒸馏）</td><td>是</td><td>是</td></tr><tr><td>快速运动与大位移为主</td><td>慎用（需覆盖轨迹或提高档位）</td><td>否</td><td>是</td></tr></tbody></table>\n<p>失效条件要写进SLO契约而非留在调参笔记里。第一类是分布错配：换基座模型未重蒸馏而直接复用学生权重，步索引嵌入与教师轨迹分布不匹配，输出出现系统性过饱和与色彩偏移，这类退化在监控上表现为色彩直方图漂移而非时延异常，容易被误判为量化问题。第二类是引导强度未重校准：CFG蒸馏去掉双分支后前向计算减半，但少步采样下条件控制减弱，文本对齐与运动幅度同时退化，需在蒸馏后重新标定引导强度而非沿用教师配置。第三类是多样性上限：少步蒸馏损失运动多样性，快速运动与大位移场景易出现拖影与时域坍缩，上限受教师轨迹覆盖范围约束，只能在蒸馏数据中补大位移轨迹或把步数档位从2步提到4/8步，后者直接按比例抬高<span class=\"formula\">$$T_{\\text{gen}}$$</span>。量化叠加时，FP8/NVFP4的误差被一致性约束部分吸收，但这一吸收依赖<span class=\"formula\">$$\\lambda\\mathcal{L}_{\\text{cons}}$$</span>的有效性，若一致性约束在低步数下已接近失效，量化误差会与过饱和叠加放大。</p>\n<p>规模上限的判断落在重蒸馏成本上：步数档位可在2/4/8步间按SLO切换，但每换一次基座模型就要重跑教师轨迹生成与蒸馏管线，这条管线的GPU时延开销与教师采样步数成正比，属于离线成本而非服务成本。因此决策顺序应是：先确认基座模型在服务周期内是否稳定，稳定则把蒸馏作为主杠杆并按SLO锁定档位；不稳定则退到缓存复用或解码侧优化，把步数压缩留到模型冻结后再做。对交互式与流式服务，4步档位配合CFG蒸馏是时延与运动保真之间的工程平衡点，2步档位只在运动幅度可控的内容形态上启用。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 视频 VAE 与时空 token 压缩</td></tr><tr><td>解决什么</td><td>视频扩散默认50步采样，端到端时延被采样步数线性放大，交互式与流式服务无法满足SLO。</td></tr><tr><td>一句话机制</td><td>用轨迹匹配蒸馏把多步教师轨迹压缩到2–8步学生，学生单步直接预测更大时间跨度的去噪增量。</td></tr><tr><td>代价与失效</td><td>少步蒸馏损失运动多样性，快速运动与大位移场景易出现拖影与时域坍缩；蒸馏需教师轨迹数据与额外训练管线，换基座模型需重蒸馏</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-step-distill-4step · 共 8 个片段</p>\n";break;}}})();
